window.DRIVE_COURSE={"chapters":[{"id":"roads","number":"01","title":"Read the road","description":"Lanes, cycle paths & the places you drive.","image":"motorway-exit.webp","lessons":[1,2,3,4,5,6]},{"id":"people","number":"02","title":"People come first","description":"Spot the people who need extra space.","image":"child-cyclist.webp","lessons":[7,8]},{"id":"car","number":"03","title":"Know your car","description":"Weight, passengers, lights & equipment.","image":"tunnel.webp","lessons":[9,10,11]},{"id":"speed","number":"04","title":"Speed & stopping","description":"Choose a safe speed. Leave room to react.","image":"school-zone.webp","lessons":[12,13]},{"id":"passing","number":"05","title":"Passing & overtaking","description":"When to pass, and when to wait.","image":"passing-cyclist.webp","lessons":[14,15,16]},{"id":"priority","number":"06","title":"Who goes first?","description":"Junctions, signals, turns & public transport.","image":"priority-from-right.webp","lessons":[17,18,19,20,21,22]},{"id":"direction","number":"07","title":"Choose your direction","description":"Read restrictions, arrows & exceptions.","image":"mandatory-straight.webp","lessons":[23,24]},{"id":"parking","number":"08","title":"Stop & park","description":"Find a legal space and decode the signs.","image":"parking-disc.webp","lessons":[25,26,27]},{"id":"safety","number":"09","title":"Stay safe","description":"Fitness, emergencies & a healthy car.","image":"reflective-vest.webp","lessons":[28,29,30,31]}],"lessons":[{"id":1,"chapter":"roads","title":"The public road","pages":[1,8],"cards":[{"title":"See the whole road","intro":"The public road is more than the part cars drive on. It can include the carriageway, cycle paths, pavements and verges.","facts":["The carriageway is the part normally used by vehicles. A lane is a marked strip within it.","A pavement is for pedestrians. A marked cycle path is reserved for the users allowed on it.","Road rules can apply on a privately owned road when it is open to public traffic. Ownership alone does not decide."],"remember":"Carriageway ≠ the entire public road.","more":"","image":"road-anatomy.webp"},{"title":"Keep right, look ahead","intro":"On an ordinary road, drive as close to the right-hand edge of the carriageway as appropriate.","facts":["Allow safe space beside parked vehicles and vulnerable users. Keeping right does not mean squeezing past a cyclist.","Use mirrors and check blind spots before changing your position.","Approach bends and crests at a speed that lets you stop within the distance you can see."],"remember":"Your lane position should leave you room to react.","more":"Lane-choice exceptions exist on one-way roads and, in built-up areas, on roads with at least two lanes in your direction. Signs and lane arrows still govern.","image":"public-road.webp"},{"title":"Read signs in layers","intro":"First recognise the sign family, then read its symbol and any supplementary plate.","facts":["A red-bordered triangle usually warns of a hazard. A red-bordered circle usually restricts you.","Blue circles usually give mandatory instructions. Rectangular signs give information or zone rules.","STOP is an octagon; give way is an inverted triangle. Their shapes help you recognise them even from behind."],"remember":"Shape first. Symbol second. Extra plate third.","more":"A zone rule continues throughout the zone until its end sign; do not assume a junction cancels it.","image":"yield-sign.webp"}],"source":"code","minutes":5},{"id":2,"chapter":"roads","title":"Lanes & road markings","pages":[9,17],"cards":[{"title":"Solid or broken?","intro":"Road markings tell you where you may move. Treat each line as a decision, not decoration.","facts":["Do not cross a continuous white line or drive astride it. A broken white line may be crossed when safe.","With a solid and broken line side by side, obey the line closest to you.","Temporary orange markings take precedence over ordinary white markings in roadworks."],"remember":"The line nearest you controls your move.","more":"","image":"lane-markings.webp"},{"title":"Merge like a zipper","intro":"When traffic is moving very slowly and a lane ends or is blocked, use alternating merging immediately before the narrowing.","facts":["Continue in your lane until the merge point. Do not force an early merge far back in the queue.","Drivers in the continuing lane let one vehicle from the ending lane enter, then continue in turn.","When lanes on both sides end, the continuing lane first admits one from the right and then one from the left."],"remember":"Very slow traffic + lane reduction = take turns at the pinch point.","more":"Zipper merging does not give normal motorway entering traffic priority over vehicles already on the motorway.","image":"zipper-merge.webp"},{"title":"Arrows, islands & reserved lanes","intro":"Get into the correct lane in good time. A painted route can be just as important as a roadside sign.","facts":["Follow the directions shown by lane arrows at the junction.","Do not drive, stop or park on hatched areas or traffic islands.","A bus lane or special reserved track is not an extra lane for a car. Only enter where the specific rules allow it, such as permitted positioning before a turn."],"remember":"Never use the hatched area as a shortcut.","more":"","image":"motorway-exit.webp"}],"source":"code","minutes":5},{"id":3,"chapter":"roads","title":"Cycle paths & cycle zones","pages":[18,25],"cards":[{"title":"A cycle path is a space, not a colour","intro":"Two parallel broken white lines or a mandatory path sign can identify a cycle path. Red paint by itself is not the legal definition.","facts":["A suggested cycle strip is part of the carriageway; it is different from a reserved cycle path.","Cross a cycle path carefully to turn or access a property, giving way to its users.","Never stop or park on a cycle path, even briefly to drop someone off."],"remember":"Look for markings and signs, not just red surfacing.","more":"","image":"shared-cycle-pedestrian-sign.webp"},{"title":"In a cycle zone, be a guest","intro":"A cycle zone has a maximum speed of 30 km/h. Motor vehicles may enter when otherwise permitted, but may not overtake cyclists.","facts":["Cyclists can use the whole width of a one-way carriageway, or the right-hand half on a two-way road.","The zone continues until its end sign, including across junctions.","Leave space and follow patiently. A cyclist riding centrally is not an invitation to squeeze past."],"remember":"30 km/h. Stay behind the cyclist.","more":"Current wording is “cycle zone” (fietszone). The book’s statement that a bicycle street automatically ends at the next junction is outdated.","image":"child-cyclist.webp"},{"title":"A cycle crossing is not a zebra crossing","intro":"A cyclist approaching a separate cycle crossing does not automatically have the same priority as a pedestrian at a zebra crossing.","facts":["Approach with care and reduce speed. Do not endanger someone already crossing.","A cyclist crossing must take account of approaching traffic and obey signals or priority signs.","When you turn across a cycle path on the road you are leaving or joining, you must give way to its users."],"remember":"Check the type of crossing and the manoeuvre you are making.","more":"Never read this distinction as permission to drive at a cyclist. You always need enough space and time to avoid a collision.","image":null}],"source":"code","minutes":5},{"id":4,"chapter":"roads","title":"Motorways","pages":[26,37],"cards":[{"title":"Enter smoothly, exit early","intro":"Use the acceleration lane to match traffic speed and find a safe gap. Vehicles already on the motorway have priority.","facts":["The normal maximum for a passenger car is 120 km/h unless a lower limit applies.","A vehicle must be capable of reaching 70 km/h on level ground to be admitted. This is not a minimum you must maintain in congestion.","No pedestrians, cyclists, mopeds or agricultural vehicles. Never reverse, turn around or use the median."],"remember":"An entry lane helps you join; it does not give you priority.","more":"","image":"motorway-hard-shoulder.webp"},{"title":"The hard shoulder is for emergencies","intro":"A missed exit is inconvenient. A sudden swerve, reverse or stop is dangerous.","facts":["Continue to the next exit if you miss yours. Never reverse back.","Do not drive or stop on the hard shoulder except for a genuine emergency or an explicitly opened rush-hour lane.","If you break down, use hazard lights, stop as far right as possible, put on a reflective vest and get behind the barrier when safe."],"remember":"Missed your exit? Take the next one.","more":"","image":"motorway-exit.webp"},{"title":"Make the rescue corridor early","intro":"When a queue forms on a road with at least two lanes in your direction, create space for emergency vehicles before they arrive.","facts":["Traffic in the far-left lane moves left. Every other lane moves right.","Keep the corridor open between the leftmost lane and the lane beside it.","Do not follow an emergency vehicle through the corridor. It is not a passing lane."],"remember":"Left lane left. All others right.","more":"Move within the available safe space; the obligation does not authorise endangering people or treating the hard shoulder as an ordinary lane.","image":"rescue-corridor.webp"}],"source":"code","minutes":5},{"id":5,"chapter":"roads","title":"Road types & speed defaults","pages":[38,43],"cards":[{"title":"Recognise the road you are on","intro":"A motorway and a motor road have different access signs. A motor-road sign does not, by itself, make the limit 120 km/h.","facts":["Motorways and motor roads exclude pedestrians and cyclists.","On a road with at least two lanes in each direction separated by a physical central reservation, the normal car maximum is 120 km/h unless signs lower it.","A painted central strip is not a physical reservation."],"remember":"Identify the road layout before choosing the default limit.","more":"","image":"temporary-road-markings.webp"},{"title":"An ordinary road outside town","intro":"For a passenger car on an ordinary road outside a built-up area, the regional default matters.","facts":["Flanders: normally 70 km/h.","Wallonia: normally 90 km/h. Brussels: normally 70 km/h outside built-up areas, and 30 km/h inside them.","Posted limits and road-layout exceptions take precedence. On a Flemish road with two or more lanes each way but only painted separation, the default is still 70 km/h."],"remember":"For your Flemish exam: ordinary road outside town = 70.","more":"A lower sign, a zone, vehicle restrictions and conditions can all require a lower speed. Never infer 90 just because a road is wide.","image":null},{"title":"Signs beat assumptions","intro":"Speed restrictions can apply to a short stretch, a whole zone or specific vehicles.","facts":["A circular speed-limit sign usually applies from the sign until the next junction, unless replaced, ended or governed by a different provision.","A speed-zone sign applies throughout the zone until the end-zone sign.","A built-up-area boundary changes the general default; a different posted limit can apply."],"remember":"A junction does not cancel a zone.","more":"","image":"school-zone.webp"}],"source":"code","minutes":5},{"id":6,"chapter":"roads","title":"Special places","pages":[44,56],"cards":[{"title":"In town, expect people","intro":"The built-up-area sign defines the legal boundary. Buildings alone do not tell you the speed limit.","facts":["Flanders and Wallonia: the normal built-up-area car limit is 50 km/h.","Brussels: normally 30 km/h unless a sign permits another speed.","A signed school zone is 30 km/h. Respect active variable signs and the indicated zone boundaries."],"remember":"In Flanders, 50 in town; 30 in a signed zone.","more":"","image":"school-zone.webp"},{"title":"Residential areas: walking pace matters","intro":"In a signed residential or home zone (woonerven / erven), pedestrians may use the full width of the road.","facts":["The maximum is 20 km/h. Children may play in the street.","Do not endanger or obstruct pedestrians; stop if necessary.","Park only in spaces indicated by markings or signs."],"remember":"20 km/h, pedestrians throughout, marked parking only.","more":"","image":"speed-20.webp"},{"title":"Play streets & pedestrian areas","intro":"Some streets are temporarily or permanently reserved for people, with limited vehicle access.","facts":["A play street is closed to ordinary through traffic during the hours shown. Permitted drivers travel at walking pace and give pedestrians priority.","Pedestrian areas admit only specifically allowed vehicles or users at indicated times. Do not assume living nearby grants every access right.","Read supplementary plates for time windows, delivery access and local exceptions."],"remember":"The plate tells you who may enter, and when.","more":"A sign allowing local traffic is a restriction on through traffic, not an exemption from other speed or priority rules.","image":null}],"source":"code","minutes":5},{"id":7,"chapter":"people","title":"Pedestrians","pages":[57,62],"cards":[{"title":"At a zebra crossing, prepare to stop","intro":"Approach an unsignalised pedestrian crossing at a moderate speed. Give way to people on it or about to step onto it.","facts":["A pedestrian clearly preparing to cross does not need to step into your lane first.","Never pass a vehicle approaching or stopped at an unsignalised pedestrian crossing. It may be hiding someone.","Keep crossings clear in a queue. Do not stop on the stripes."],"remember":"Slow down before the crossing, not on it.","more":"Signals govern a controlled crossing, but a green light does not let you endanger pedestrians finishing their crossing.","image":null},{"title":"When you turn, people continue","intro":"Turning changes your route. It does not erase a pedestrian’s route along the road.","facts":["Give way to pedestrians crossing the carriageway you are turning into.","Give way to pedestrians crossing the road you are leaving, as required when turning.","Check beside you and behind you for cyclists before crossing their path."],"remember":"Before turning: mirrors, blind spot, crossing users.","more":"","image":null},{"title":"Give vulnerable people more room","intro":"Children, older people and people with reduced mobility may move or react unpredictably.","facts":["Slow down and be ready to stop near schools, buses, parked cars and groups of children.","Leave at least 1 metre when passing a pedestrian on the carriageway in a built-up area; outside it, at least 1.5 metres.","Do not open a car door into the path of a pedestrian or cyclist. Check first."],"remember":"A small speed reduction buys a lot of reaction time.","more":"","image":"child-cyclist.webp"}],"source":"code","minutes":5},{"id":8,"chapter":"people","title":"Drivers & attention","pages":[63,65],"cards":[{"title":"Who is a driver?","intro":"“Driver” is broader than someone in a car. A cyclist, a rider and someone leading animals can be drivers too.","facts":["Priority from the right applies to drivers, including cyclists, unless a different rule applies.","Someone pushing a bicycle or two-wheeled moped is treated as a pedestrian.","Vehicle-category signs can apply to a car, a motorcycle or a cycle differently. Read the symbol."],"remember":"A cyclist can have the same priority as a car.","more":"","image":null},{"title":"Keep the phone out of your hands","intro":"While driving, you may not use, hold or manipulate a mobile electronic device with a screen unless it is secured in a suitable holder.","facts":["A red light or a traffic queue is still part of driving, not a parking break.","Set navigation before moving. A holder does not make distracting use safe.","Stop and park legally before handling your phone."],"remember":"Red light = still driving.","more":"This current wording is broader than the book’s older “mobile phone” language: it covers mobile devices with a screen.","image":null},{"title":"Small wheels, real road users","intro":"Electric scooters are generally treated like bicycles under the current rules. Be ready to give their riders the same priority and safe space.","facts":["Motorised mobility devices generally follow cyclist rules, rather than riding on pavements. Mobility-aid exceptions exist.","Normal electric scooters have a maximum design speed of 25 km/h. Riders generally need to be at least 16, with limited exceptions.","Since 1 September 2026, a helmet is required on motorised mobility devices whose design speed is above 20 km/h."],"remember":"A scooter can be a cyclist in the rules, and easy to miss in a blind spot.","more":"The helmet can be an approved moped helmet or a cycle helmet protecting the temples and back of the head. Treat the design-speed threshold separately from the speed at which someone is currently riding.","image":null}],"source":"code","minutes":5},{"id":9,"chapter":"car","title":"Licence B, weight & equipment","pages":[66,72],"cards":[{"title":"Maximum authorised mass is a limit","intro":"Maximum authorised mass (MAM; Dutch MTM) is the permitted loaded mass. Actual mass is what the vehicle weighs right now.","facts":["A standard category B licence generally covers vehicles up to 3,500 kg MAM and no more than 8 passenger seats in addition to the driver.","Use the vehicle documents for its limits. An empty heavy vehicle does not become a category B vehicle just because its current mass is lower.","Passengers, fuel and luggage all contribute to actual mass. Do not overload."],"remember":"Licence categories use authorised mass, not an empty-day weigh-in.","more":"","image":null},{"title":"Towing with a full B licence","intro":"Two standard B cases are worth remembering.","facts":["A trailer of up to 750 kg MAM may be towed by an eligible category B vehicle.","A trailer above 750 kg MAM can be within ordinary B if the combination’s total MAM is no more than 3,500 kg.","A B code 96 or BE entitlement can be needed for heavier combinations. Always respect the vehicle’s technical towing limit."],"remember":"Trailer ≤750, or heavier trailer with combination ≤3,500.","more":"A provisional B licence does not permit towing a trailer. Extra entitlements and limited special vehicle exceptions require their own official checks.","image":null},{"title":"Have the essentials ready","intro":"For a normal Belgian-registered car, keep the required equipment and documents available.","facts":["Equipment: warning triangle, first-aid kit and approved fire extinguisher. Keep a reflective vest reachable for motorway breakdowns.","Documents include your driving licence, registration and insurance certificate; the conformity and inspection documents must be available where required.","Check the spare-wheel or repair-kit instructions before you need them."],"remember":"A vest buried under luggage is hard to use safely.","more":"","image":"reflective-vest.webp"}],"source":"licence","minutes":5},{"id":10,"chapter":"car","title":"Passengers & loads","pages":[73,79],"cards":[{"title":"Every passenger needs a safe seat","intro":"Seat belts protect the driver and passengers in front and rear seats.","facts":["Wear the belt correctly across the shoulder and low over the hips, not under the arm.","A child under 18 who is shorter than 1.35 m normally needs a suitable child restraint.","Never use a rear-facing child seat in front of an active frontal airbag. Deactivate the airbag or use a suitable rear seat."],"remember":"Under 1.35 m: use the right child restraint.","more":"There are narrow legal exceptions for certain transport situations. Plan normal car journeys using an appropriate restraint rather than relying on an exception.","image":null},{"title":"Secure the load","intro":"Your load must not fall, drag, obstruct your view or endanger other road users.","facts":["Keep number plates, lights and indicators visible. Secure loose objects inside the car too.","For a normal car, the usual maximum loaded width is 2.55 m and height is 4 m; posted smaller clearance limits still apply.","Do not exceed the vehicle’s permitted mass, roof-load limit or towing limit."],"remember":"Heavy objects low, secured, and within the limits.","more":"","image":null},{"title":"What may project?","intro":"A passenger-car load must not project beyond the front. Rear projection has specific limits and marking rules.","facts":["The normal maximum rear projection is 1 metre.","An indivisible load may extend up to 3 metres at the rear under the applicable marking requirements.","When rear projection exceeds 1 metre, use the prescribed 50 × 50 cm red-and-white warning panel; additional light and reflectors are needed when lighting is required."],"remember":"No front projection. Check rear distance and marking.","more":"Do not confuse a warning panel for a projecting load with the warning triangle used for a breakdown. If the transport is unusual, verify Article 46 before departure.","image":null}],"source":"code","minutes":5},{"id":11,"chapter":"car","title":"Lights & the horn","pages":[80,85],"cards":[{"title":"Use lights to see and be seen","intro":"Use dipped headlights after dark, in tunnels and when visibility conditions require them.","facts":["Dipped beams and rear position lights are required between nightfall and daybreak and when you cannot see clearly for about 200 metres.","High beam must not dazzle oncoming road users or the driver ahead. Switch to dipped beam in time.","Daytime running lights may leave rear lights off; do not rely on them in a dark tunnel or poor visibility."],"remember":"DRLs are not a substitute for proper night lighting.","more":"","image":"tunnel.webp"},{"title":"Fog lights have a job","intro":"Bright fog lights can dazzle when used unnecessarily.","facts":["Rear fog lights must be used in fog or snowfall when visibility is below 100 metres, and in heavy rain.","Front fog lights may be used in fog, snowfall or heavy rain.","Switch fog lights off when the conditions no longer justify them."],"remember":"Rear: fog/snow under 100 m, or heavy rain.","more":"Hazard lights signal danger or a breakdown. They do not make illegal parking legal.","image":null},{"title":"Signal early, without misleading","intro":"Indicators inform other road users of your intended move. They do not give you priority.","facts":["Indicate before turning, changing lanes or making a manoeuvre, after checking it is safe.","Signal right when leaving a roundabout; do not mislead drivers at an earlier exit.","Use the horn only as necessary to avoid danger; outside a built-up area it may also warn a driver you intend to overtake. At night, generally use light signals instead unless danger requires the horn."],"remember":"Signal communicates a plan. It does not reserve a gap.","more":"","image":null}],"source":"code","minutes":5},{"id":12,"chapter":"speed","title":"Speed","pages":[86,97],"cards":[{"title":"Your Flemish speed ladder","intro":"For a normal car, learn the usual defaults, then look for exceptions.","facts":["20 km/h in residential/home zones; 30 km/h in signed 30 zones and cycle zones.","50 km/h in a built-up area in Flanders; 70 km/h on most ordinary roads outside it.","120 km/h on motorways and qualifying roads with a physical central reservation, unless a lower limit is shown."],"remember":"20 • 30 • 50 • 70 • 120. Context chooses the number.","more":"Wallonia generally uses 90 outside town; Brussels uses 30 in built-up areas and normally 70 on ordinary roads outside them. Limits for trailers, special vehicles and some road layouts differ.","image":"school-zone.webp"},{"title":"A limit is a ceiling, not a target","intro":"You must adapt speed to visibility, weather, road condition, traffic and the people around you.","facts":["Be able to stop before a foreseeable obstacle within the distance you can see.","Rain, ice, fog, roadworks and parked cars can require much less than the posted maximum.","Do not obstruct traffic by driving abnormally slowly without a valid reason."],"remember":"Legal maximum and safe speed can be different.","more":"","image":null},{"title":"Watch for exam wording","intro":"Speed questions often hide the key information in the road layout or regional location.","facts":["“Outside a built-up area in Flanders, ordinary two-way road, no signs” points to 70 km/h.","“Two lanes each way separated only by paint” is not the 120 km/h physical-reservation case.","“Cycle zone” means 30 km/h and no overtaking cyclists by motor vehicles."],"remember":"Name the road and region before picking a number.","more":"In the Flemish theory exam, a wrong answer about exceeding a maximum speed limit costs 5 points rather than 1. Slow down and read the scenario carefully.","image":null}],"source":"code","minutes":5},{"id":13,"chapter":"speed","title":"Stopping distance","pages":[98,101],"cards":[{"title":"Two distances make one stop","intro":"Stopping distance is reaction distance plus braking distance.","facts":["During your reaction time, the car continues moving before braking begins.","Braking distance depends on speed, tyres, grip, brakes and road slope.","Alcohol, fatigue and distraction increase reaction time; wet or icy roads increase braking distance."],"remember":"Reaction + braking = stopping.","more":"","image":null},{"title":"Double speed, much more braking","intro":"If grip and braking conditions are the same, doubling speed roughly quadruples braking distance.","facts":["Reaction distance roughly doubles when speed doubles and reaction time stays the same.","At 50 km/h, you travel about 14 metres in one second; at 100 km/h, about 28 metres.","The book’s stopping-distance tables are illustrative estimates, not guaranteed distances or universal legal formulas."],"remember":"The faster you go, the more space you need.","more":"ABS helps prevent wheel lock and preserve steering; it does not guarantee a shorter stop, especially on loose surfaces.","image":null},{"title":"Leave a gap you can use","intro":"Use a fixed roadside point to check a time gap behind the vehicle ahead.","facts":["In good conditions, use at least a two-second gap as a practical baseline.","Increase it substantially in rain, darkness, low grip or when following a vehicle that blocks your view.","If someone tailgates you, create more room ahead and avoid sharp braking."],"remember":"Two seconds is a starting point. Bad conditions need more.","more":"The legal obligation is a sufficient safety distance. A simple “speed divided by two” distance is a teaching shortcut, not a guarantee in every situation.","image":null}],"source":"code","minutes":5},{"id":14,"chapter":"passing","title":"Meeting oncoming traffic","pages":[102,107],"cards":[{"title":"Pass each other on the right","intro":"When meeting oncoming traffic, both drivers need enough room.","facts":["Keep right and leave sufficient lateral clearance. Slow or stop if the road is too narrow.","If an obstacle is on your side, normally yield to oncoming traffic before going around it.","Do not force someone onto a verge or cycle path to make your pass possible."],"remember":"Obstacle on your side? Wait for a safe gap.","more":"","image":null},{"title":"Two narrow-road priority signs","intro":"Red and black opposed arrows and a blue rectangle with opposed arrows tell you who goes first at a narrow section.","facts":["A round red-bordered sign with a red upward arrow tells you to give way to oncoming traffic.","A blue sign with a white upward arrow gives your direction priority over oncoming traffic.","Priority still requires you to avoid a collision if the narrow section is already occupied."],"remember":"A priority sign does not make the road wider.","more":"","image":null},{"title":"Space before speed","intro":"A meeting manoeuvre is easier when you anticipate the narrow part early.","facts":["Check parked cars, buses, cyclists and roadworks ahead.","Do not accelerate into a gap that requires another road user to brake sharply.","Be especially patient around a tram, large vehicle or cyclist with limited room."],"remember":"Make the safe gap before you enter it.","more":"","image":null}],"source":"code","minutes":5},{"id":15,"chapter":"passing","title":"Overtaking safely","pages":[108,114],"cards":[{"title":"Three checks before overtaking","intro":"Overtaking is normally on the left. Only start when you can complete the manoeuvre safely.","facts":["Look ahead: clear view, enough space and no prohibition.","Look behind: nobody has already started overtaking you. Check mirrors and blind spots.","Check the vehicle ahead is not signalling a left turn; return right without cutting it off."],"remember":"See enough. Have room. Check behind.","more":"","image":null},{"title":"Passing a cyclist","intro":"Leave a legal minimum lateral clearance, and more if conditions demand it.","facts":["In a built-up area: at least 1 metre.","Outside a built-up area: at least 1.5 metres.","If you cannot leave enough space without breaking another rule or endangering traffic, stay behind."],"remember":"1 m in town. 1.5 m outside. Wait if there is no room.","more":"The same lateral-clearance thresholds apply when passing pedestrians on the carriageway.","image":"passing-cyclist.webp"},{"title":"Right-side exceptions","intro":"Passing a moving vehicle on its right is generally prohibited, but specific situations differ.","facts":["You may pass a vehicle on the right when it clearly indicates and positions for a left turn, if there is enough lawful space.","Parallel slow-moving queues can progress at different speeds without each movement being an overtaking manoeuvre.","Do not move onto a hard shoulder, cycle path or prohibited area to get around someone."],"remember":"A legal exception is not permission to improvise a new lane.","more":"","image":null}],"source":"code","minutes":5},{"id":16,"chapter":"passing","title":"When overtaking is prohibited","pages":[115,123],"cards":[{"title":"If you cannot see, do not go","intro":"Passing becomes dangerous when the unseen space ahead could contain an oncoming vehicle.","facts":["Do not overtake to the left where you have insufficient visibility, such as a blind bend or crest, unless the lawful road layout makes the manoeuvre safe under the rules.","Never cross a continuous white line to overtake.","An overtaking-prohibited sign applies to the vehicle classes and manoeuvres it specifies."],"remember":"A clear view is part of permission.","more":"","image":null},{"title":"Crossings hide people","intro":"A stopped vehicle can screen a pedestrian or cyclist.","facts":["Do not overtake a vehicle approaching or stopped at an unsignalised pedestrian crossing or cycle crossing.","Never overtake on a railway crossing without barriers or traffic lights, apart from the specific narrow exceptions in the code.","Do not overtake at a junction where you must give way under the relevant priority rules."],"remember":"When a car stops at a crossing, expect someone you cannot see.","more":"Junction and level-crossing rules have specific exceptions, for example some two-wheeled vehicles. For a normal car scenario, do not assume you qualify.","image":null},{"title":"When someone overtakes you","intro":"Being overtaken is a cooperation task.","facts":["Keep as far right as appropriate and do not accelerate.","Do not close a safe gap just because the other driver has made a poor decision.","If the manoeuvre becomes dangerous, reduce risk without sudden or unpredictable movements."],"remember":"Keep right. Hold or reduce speed. Leave room.","more":"","image":null}],"source":"code","minutes":5},{"id":17,"chapter":"priority","title":"Police & emergency vehicles","pages":[124,128],"cards":[{"title":"Know the order of authority","intro":"When instructions conflict, use this order: authorised person, traffic lights, traffic signs, general rules.","facts":["An authorised officer’s instruction takes priority even over a red or green light.","A raised arm means stop for road users, apart from drivers who cannot safely stop and those already in the junction who must clear it.","One or both arms extended horizontally means stop for traffic approaching from directions crossing the indicated line."],"remember":"Person → lights → signs → general rules.","more":"Other authorised people can have limited powers, such as helping children cross. Their permitted instructions must be respected.","image":null},{"title":"Blue lights and siren","intro":"When a priority vehicle announces its approach with its special audible warning, immediately clear a passage, give way and stop if necessary.","facts":["Check mirrors and move predictably into safe space.","Do not drive into a junction blindly or endanger pedestrians to make room.","Create a rescue corridor early in a queue on roads with multiple lanes in your direction."],"remember":"Make space safely; do not wait for the siren to be beside you.","more":"","image":"rescue-corridor.webp"},{"title":"Stay out of the emergency route","intro":"An emergency response works best when ordinary drivers stay predictable.","facts":["Do not follow a priority vehicle through a cleared corridor.","Keep junctions, crossings and access routes free.","Call 112 for a life-threatening emergency; give your location and the nature of the danger."],"remember":"Help by leaving room, not by following.","more":"","image":null}],"source":"code","minutes":5},{"id":18,"chapter":"priority","title":"Traffic lights","pages":[129,139],"cards":[{"title":"Red, amber, green","intro":"Traffic lights control entry. A green signal is permission to proceed only when the route is clear and safe.","facts":["Red: stop before the stop line, or before the signal if there is no line.","Steady amber: stop unless you are so close that you cannot stop safely. Do not speed up to beat it.","Green: proceed, but do not enter a blocked junction or ignore crossing users."],"remember":"Green does not reserve space beyond the junction.","more":"","image":null},{"title":"Flashing amber & arrows","intro":"A flashing amber light warns you to be especially careful; other priority rules still apply.","facts":["When lights are inactive or flashing amber, obey priority signs, then the general priority rules.","A green arrow can allow movement only in its indicated direction; obey the applicable yielding duties.","A small cyclist-only right-turn or straight-on permission does not apply to a car."],"remember":"Flashing amber is caution, not automatic priority.","more":"","image":null},{"title":"Lane signals & railway signals","intro":"Signals can close a lane or warn of a train even when the road ahead looks empty.","facts":["A red cross above a lane means you must not use that lane. A green downward arrow opens it, subject to other rules.","At a railway crossing, stop when red lights flash, the audible warning sounds, or barriers close or are closing.","Never enter a railway crossing unless you can clear it completely."],"remember":"Red railway signal: wait, even if the barrier is still up.","more":"","image":"level-crossing.webp"}],"source":"code","minutes":5},{"id":19,"chapter":"priority","title":"Priority signs & roundabouts","pages":[140,152],"cards":[{"title":"Priority road, give way, STOP","intro":"These signs change who goes first. Learn the behaviour as well as the shape.","facts":["Yellow diamond: priority road. Follow its route, including a supplementary diagram if the priority road bends.","Inverted red triangle: give way; stop if necessary.","STOP octagon: come to a complete stop, then give way. Stop at the line, or before entering the junction if no line is marked."],"remember":"Give way may need a stop. STOP always needs one.","more":"","image":"priority-road-junction.webp"},{"title":"Shark teeth & stop lines","intro":"White triangles mark a give-way position; a solid transverse stop line marks where to stop for STOP or a red signal.","facts":["Slow before shark teeth and give way to traffic with priority.","At STOP, a rolling slowdown is not a full stop.","Check for a cycle path crossing your approach before you focus on cars on the main road."],"remember":"Look near first: a cycle path may be before the main road.","more":"","image":"shark-teeth.webp"},{"title":"A roundabout is a sequence","intro":"The give-way signs at a normal roundabout entry give circulating traffic priority.","facts":["Give way at the entrance. You do not need to indicate just to enter.","Choose and change lanes safely; changing lanes is a manoeuvre and requires giving way.","Indicate right before leaving and check for pedestrians and cyclists crossing your exit."],"remember":"Entry: give way. Exit: signal and check.","more":"Do not infer priority from a circular road alone: look at the actual signs. A driver in an inner lane does not have priority to cut across an outer-lane driver.","image":null}],"source":"code","minutes":5},{"id":20,"chapter":"priority","title":"Priority from the right","pages":[153,160],"cards":[{"title":"At an equal junction, look right","intro":"Without an officer, working lights or priority signs changing the rule, give way to a driver coming from your right.","facts":["It applies to cars and cyclists. A wider or busier road is not automatically a priority road.","A driver from the right does not lose priority simply because they have stopped.","An unpaved track or path entering a public road is a specific exception; that entering driver must give way."],"remember":"No other instruction? Check right.","more":"","image":"priority-from-right.webp"},{"title":"Turning does not remove priority","intro":"The direction the driver from the right intends to take does not automatically cancel priority from the right.","facts":["A vehicle from the right can still have priority when turning toward you or across your route.","Do not rely on eye contact alone. Slow enough to stop if necessary.","Priority from the right does not apply in favour of someone coming from a direction where driving is prohibited."],"remember":"Watch where they come from, then where they are going.","more":"","image":"priority-from-right-turning.webp"},{"title":"A manoeuvre must yield","intro":"Reversing, leaving a parking space, changing lanes or turning around are manoeuvres.","facts":["The driver performing a manoeuvre gives way to other road users.","Coming out of private property or a driveway is a manoeuvre, not ordinary priority from the right.","Indicators tell others what you intend; they do not make them give way to you."],"remember":"Manoeuvre = give way to everyone affected.","more":"","image":null}],"source":"code","minutes":5},{"id":21,"chapter":"priority","title":"Turning & positioning","pages":[161,163],"cards":[{"title":"Prepare the turn early","intro":"Choose a safe position, reduce speed and signal in good time.","facts":["For a right turn, approach near the right-hand edge while respecting cycle paths and vulnerable users.","For a left turn on a two-way road, position toward the centre without entering the oncoming side. On a one-way road, position toward the left edge as appropriate.","Check mirrors and blind spots before moving across someone’s line."],"remember":"Plan the turn before the junction.","more":"","image":null},{"title":"Left turn: let oncoming traffic pass","intro":"When turning left, give way to oncoming traffic continuing straight or turning right.","facts":["Do not cut diagonally across the opposing lane.","When two vehicles turn left, follow the prescribed junction layout and pass in the appropriate way.","Wait where you do not obstruct a crossing or block the junction."],"remember":"Turning left usually means waiting for oncoming traffic.","more":"","image":null},{"title":"Protect the crossing route","intro":"People continuing along the road may be beside your vehicle rather than directly ahead.","facts":["Give way to users of the cycle path you cross when turning.","Give way to pedestrians crossing the road you enter or leave.","If your view is blocked by a van or parked car, slow further and check before committing."],"remember":"The final check is beside you, not just in front.","more":"","image":null}],"source":"code","minutes":5},{"id":22,"chapter":"priority","title":"Trains, trams & buses","pages":[164,173],"cards":[{"title":"A railway crossing must stay clear","intro":"A train cannot steer around you and needs a long distance to stop.","facts":["Never enter a crossing if a queue prevents you from clearing the tracks.","Stop for red flashing lights, the audible warning or closing/closed barriers.","If trapped on the tracks, prioritise getting people out and away; call 112 and report the exact crossing."],"remember":"Only enter when your exit is clear.","more":"","image":"level-crossing.webp"},{"title":"Trams have special priority","intro":"Rail vehicles generally have priority over other road users, even when they come from the left.","facts":["Police instructions and applicable traffic lights still take precedence.","Do not stop or park on tram tracks.","Be careful near passengers boarding or leaving a tram when there is no protected platform."],"remember":"Tram from the left can still go first.","more":"A tram does not get permission to disregard a red light just because it is on rails.","image":null},{"title":"Let a bus leave its stop in town","intro":"In a built-up area, a bus or trolleybus signalling to leave its stop must be allowed to rejoin traffic.","facts":["Slow and stop if necessary to let it pull out.","Outside a built-up area, this specific departure-priority rule does not apply; still drive defensively.","Parking is prohibited within 15 metres before and after a bus/tram stop sign, unless the permitted arrangement specifies otherwise."],"remember":"Bus signals out in town? Let it go.","more":"","image":"bus-stop.webp"}],"source":"code","minutes":5},{"id":23,"chapter":"direction","title":"Prohibited directions","pages":[174,179],"cards":[{"title":"No entry is not no traffic","intro":"A red disc with a horizontal white bar prohibits entry from your direction. A white circle with a red border prohibits traffic in both directions, subject to exceptions.","facts":["A no-entry sign often marks the wrong end of a one-way road.","Read plates: an exception for cyclists does not include a car.","A forbidden turn sign prohibits the pictured turn. Check whether a separate U-turn prohibition applies."],"remember":"Read your direction and your vehicle category.","more":"","image":null},{"title":"Local traffic & restrictions","intro":"Some roads exclude through traffic, certain vehicle types or vehicles over a size or mass limit.","facts":["Local access can include destinations on the restricted road, but it is not a shortcut permission.","A number for height, width or length includes the load.","Mass restrictions and axle-load restrictions are different; look at the exact symbol."],"remember":"The load counts for a clearance limit.","more":"Do not confuse a sign about actual loaded mass with your licence category, which uses maximum authorised mass.","image":null},{"title":"One-way does not mean no surprises","intro":"A one-way road can have two-way cycling when signs explicitly allow it.","facts":["Look for exception plates permitting cyclists or mopeds in the opposite direction.","Keep checking both ways at junctions and before opening your door.","A vehicle lawfully approaching from the right under a cycle exception may have priority from the right."],"remember":"One-way for cars can be two-way for cycles.","more":"","image":null}],"source":"code","minutes":5},{"id":24,"chapter":"direction","title":"Mandatory directions","pages":[180,182],"cards":[{"title":"A blue circle tells you what to do","intro":"Mandatory-direction signs require the direction or side shown.","facts":["A straight-ahead arrow requires going straight at the relevant location.","An arrow pointing down and diagonally tells you which side of an obstacle to pass.","A supplementary bicycle or moped exception applies only to the indicated categories."],"remember":"Blue circle: obey the pictured instruction.","more":"","image":"mandatory-straight.webp"},{"title":"Combine arrows with lane position","intro":"Signs and lane arrows work together. Plan early enough to obey both safely.","facts":["A directional arrow in your lane determines permitted movements from that lane.","Do not make a sudden prohibited lane change to reach an exit or turn.","If you are in the wrong lane, follow its legal direction and find another route."],"remember":"Wrong lane? Take the safe legal route.","more":"","image":"lane-arrows.webp"},{"title":"A route instruction is not priority","intro":"Being required to go one way does not tell you who goes first.","facts":["Continue to obey traffic lights, give-way signs and crossings.","A mandatory turn can still require you to yield to pedestrians or cyclists.","Changing lanes to follow a route remains a manoeuvre."],"remember":"Direction answers “where”; priority answers “when”.","more":"","image":null}],"source":"code","minutes":5},{"id":25,"chapter":"parking","title":"Stopping & parking basics","pages":[183,194],"cards":[{"title":"Stopping is an activity, not a duration","intro":"Legally stopping means only the time needed for people to get in or out, or for loading or unloading.","facts":["Waiting for a friend to arrive is parking, even if you stay in the driver’s seat or leave the engine running.","Waiting at a red light or in traffic is not legal stopping/parking in this sense.","Hazard lights do not change a parked vehicle into a loading stop."],"remember":"Necessary boarding/loading = stopping. Waiting = parking.","more":"","image":null},{"title":"Position the vehicle correctly","intro":"Normally stop or park on the right in your direction of travel and as close as possible to the edge.","facts":["On a one-way road, either side can be allowed.","Use a suitable lawful verge when the rules require it, preserving pedestrian access.","Do not double park, block a cycle path or obstruct a pavement. Keep at least 1.5 m for pedestrians where the verge rule applies."],"remember":"Being “just a minute” does not remove the obstruction.","more":"","image":"parking-on-cycle-lane.webp"},{"title":"Places where neither is allowed","intro":"Some locations prohibit both stopping and parking because visibility or access is critical.","facts":["Do not stop or park on crossings, cycle paths, pavements, railway crossings, traffic islands or motorway lanes/shoulders.","On the carriageway, keep at least 5 m before a pedestrian or cycle crossing.","At junctions, keep at least 5 m from the extension of the nearest edge of the crossing carriageway, unless a permitted local arrangement applies."],"remember":"Crossing itself: never. Before it on the carriageway: 5 m.","more":"Further restrictions apply near signs/lights, dangerous bends, hill crests, bridges and tunnels. Do not park where you obscure a signal or create danger.","image":null}],"source":"code","minutes":5},{"id":26,"chapter":"parking","title":"Parking signs & restrictions","pages":[195,203],"cards":[{"title":"One bar or a cross?","intro":"The red-and-blue sign with one diagonal bar prohibits parking. The cross prohibits both stopping and parking.","facts":["An E1 no-parking sign can still permit genuine loading or boarding if no other rule prohibits stopping.","An E3 no-stopping/no-parking sign prohibits both activities.","The restriction applies on the side of the road where the sign is placed; supplementary plates and zone rules define its extent."],"remember":"One bar = no parking. Cross = no stopping either.","more":"","image":"no-parking-sign.webp"},{"title":"Yellow lines, driveways & narrow roads","intro":"Parking-only restrictions can apply without a red-and-blue sign.","facts":["A broken yellow line at the carriageway edge prohibits parking along it.","Do not park where less than 3 m of free carriageway remains, or where you block vehicle access to a property.","Keep the required space around parked vehicles and bus stops. Accessible spaces require a valid parking card displayed and the eligible person’s use."],"remember":"Broken yellow line = no parking.","more":"A property entrance can have a plate-number exception for the identified vehicle. General danger or obstruction rules still apply.","image":"yellow-parking-line.webp"},{"title":"Read the supplementary arrow","intro":"A small arrow below a parking restriction tells you which stretch it covers.","facts":["Arrow up: the restriction starts beyond the sign. Arrow down: the restriction ends at the sign.","Arrows both ways: it applies before and beyond the sign. A distance plate can define the length.","Time windows, vehicle symbols and alternate-half-month rules may limit when or to whom it applies."],"remember":"The main sign tells the rule; the plate tells the scope.","more":"For half-month alternating parking, the changeover on the final day of a period is between 19:30 and 20:00. Check the sign, rather than assuming an odd/even calendar-date rule.","image":"no-stopping-sign.webp"}],"source":"code","minutes":5},{"id":27,"chapter":"parking","title":"Blue zones & leaving the car","pages":[204,210],"cards":[{"title":"Use the parking disc correctly","intro":"In a standard blue zone, a parking disc is required on working days, normally Monday to Saturday, between 09:00 and 18:00, unless signs say otherwise.","facts":["Display the disc clearly behind the windscreen.","Set it to the next half-hour mark following your arrival. For arrival at 10:10, set 10:30.","Normally you may park for 2 hours from the indicated time. A sign can specify a different duration."],"remember":"10:10 arrival → 10:30 on the disc → normally until 12:30.","more":"","image":"parking-disc.webp"},{"title":"Do not reset the disc while staying","intro":"When your permitted time ends, move the vehicle; merely changing the disc is not allowed.","facts":["Blue-zone conditions can apply across junctions until the zone end.","A parking-disc plate can also require a disc outside a zone.","Follow local payment instructions. If the parking machine is out of order, the code’s parking-disc rule may apply."],"remember":"Moving the dial is not moving the car.","more":"","image":"blue-zone.webp"},{"title":"Check before opening the door","intro":"Secure the vehicle, then check for people approaching beside it.","facts":["Apply the parking brake and secure the car against rolling.","Check mirrors and look over your shoulder before opening a door. Using the opposite hand can help you turn to look.","Do not leave an engine running unnecessarily; lock the car and keep valuables out of sight."],"remember":"A door opening is a road-safety decision.","more":"","image":null}],"source":"code","minutes":5},{"id":28,"chapter":"safety","title":"Alcohol, drugs & fatigue","pages":[211,214],"cards":[{"title":"Know the ordinary alcohol threshold","intro":"For ordinary car drivers, the punishable threshold starts at 0.5 g/l in blood (0.5‰) or 0.22 mg/l in exhaled air.","facts":["A lower threshold applies to certain professional transport drivers.","Alcohol impairs judgement before you feel obviously drunk.","Time lowers alcohol levels; coffee, a shower or fresh air do not make you sober."],"remember":"Safest plan: if you drive, do not drink.","more":"","image":"breathalyser.webp"},{"title":"Drugs & medicines count too","intro":"Being under the influence of drugs is prohibited. Some legal medicines can also make driving unsafe.","facts":["Do not assume a prescription guarantees you are fit to drive.","Read warnings and ask a pharmacist about drowsiness, reaction time and interactions with alcohol.","Police can carry out testing under the applicable procedures; refusal is not a way to avoid the rules."],"remember":"Legal to take does not always mean safe to drive.","more":"","image":null},{"title":"Sleep is a safety system","intro":"Drowsiness can produce microsleeps: brief lapses during which you are not controlling the road situation.","facts":["Repeated yawning, drifting position and missing signs are reasons to stop safely.","Opening a window or turning up music is not a reliable fix.","Plan rest breaks, and rest before continuing if sleepy."],"remember":"Stop before your attention stops.","more":"Alcohol-enforcement procedures and licence measures change. This course teaches the driving rules and avoids reproducing the book’s dated penalty tables.","image":null}],"source":"code","minutes":5},{"id":29,"chapter":"safety","title":"Breakdowns & collisions","pages":[215,224],"cards":[{"title":"Protect the scene first","intro":"Avoid creating a second collision. Move to safety when possible and warn approaching road users.","facts":["Use hazard lights. On a motorway, wear a reflective vest before leaving the car and get behind the barrier when safe.","Place a warning triangle at least 30 m behind on an ordinary road and at least 100 m on a motorway, when it can be done safely.","In a built-up area where the distance is impossible, place it at a smaller distance, potentially on the vehicle, following the code."],"remember":"People first. Visibility second. Paperwork later.","more":"","image":"warning-triangle.webp"},{"title":"Injuries: call 112","intro":"If anyone is injured, stop, help within your ability, and contact emergency services.","facts":["Give the exact location, number of casualties and hazards. On a motorway, use direction, exit or kilometre marker.","Do not move an injured person unless immediate danger makes it necessary.","Follow the emergency operator’s instructions. Never put yourself in danger trying to place equipment."],"remember":"112 needs a location and a clear description.","more":"In a tunnel, use the emergency equipment and signed escape routes; do not turn around or reverse to escape a queue.","image":"reflective-vest.webp"},{"title":"After a damage-only collision","intro":"Stop and exchange the required identity and vehicle details. Record the facts calmly.","facts":["Take useful photos if it is safe, including position, damage and signs.","Complete a European accident statement accurately; check the diagram and boxes before signing.","If there is a dispute, refusal to exchange details, injuries or another reason police assistance is needed, contact police."],"remember":"Leaving without the required duties can be a hit-and-run.","more":"Do not stand between vehicles or in a live lane to argue about fault. Insurers assess responsibility using the evidence.","image":null}],"source":"code","minutes":5},{"id":30,"chapter":"safety","title":"Efficient driving","pages":[225,230],"cards":[{"title":"Smooth driving saves attention and fuel","intro":"Look far enough ahead to anticipate slowing traffic rather than repeatedly accelerating and braking.","facts":["Accelerate smoothly and use a suitable higher gear without labouring the engine.","Ease off early when approaching a red light or queue.","Maintain a steady safe speed and avoid unnecessary idling."],"remember":"Look ahead. Ease off early. Drive smoothly.","more":"","image":null},{"title":"Reduce resistance","intro":"The vehicle needs more energy when it pushes extra air or carries unnecessary weight.","facts":["Remove an unused roof box or carrier.","Use the manufacturer’s correct cold tyre pressures for the load.","Do not carry heavy items unnecessarily; maintain the car regularly."],"remember":"Correct pressure and less roof drag are easy wins.","more":"Do not copy a universal pressure increase from an old book. Use the vehicle’s pressure label and handbook.","image":null},{"title":"Plan a legal route","intro":"A route must be legal for your vehicle as well as convenient.","facts":["Check local low-emission-zone rules when entering cities; eligibility depends on current local policy and vehicle details.","Combine trips where practical and consider walking, cycling or public transport for short journeys.","Never sacrifice visibility, ventilation or safety to save a little energy."],"remember":"Eco-driving starts with planning, not with risky shortcuts.","more":"","image":null}],"source":"code","minutes":5},{"id":31,"chapter":"safety","title":"Tyres, brakes & assistance","pages":[231,239],"cards":[{"title":"Your tyres are the contact patch","intro":"Tyre condition affects grip, braking and control.","facts":["The minimum tread depth for a normal car tyre is 1.6 mm in the main grooves. Replace worn or damaged tyres in good time.","Check pressure with cold tyres, using the manufacturer’s specification for your load.","Worn tread and standing water increase aquaplaning risk. Reduce speed and avoid abrupt steering or braking if grip is lost."],"remember":"1.6 mm is the legal minimum, not a promise of good wet grip.","more":"The book’s “change tyres every 10,000–15,000 km” should not be treated as a replacement rule. Inspection, wear, age, damage and manufacturer guidance determine maintenance.","image":null},{"title":"ABS helps you keep steering","intro":"ABS prevents sustained wheel lock during heavy braking. You may feel the pedal pulse.","facts":["In an emergency with ABS, press the brake firmly and maintain pressure while steering as necessary.","Do not pump the pedal as you might have been taught for old non-ABS systems.","ABS does not guarantee a shorter braking distance on every surface."],"remember":"Firm pressure. Keep steering. Do not pump.","more":"","image":null},{"title":"ESP helps, but physics still wins","intro":"Electronic stability control helps correct loss of stability by reducing power and braking individual wheels.","facts":["It cannot create grip that the tyres and road do not have.","Brake, oil-pressure or other serious warnings need the response specified in your handbook; stop safely when required.","Driver assistance never replaces checking mirrors, controlling speed and maintaining space."],"remember":"Assistance supports you; it does not take responsibility.","more":"","image":null}],"source":"code","minutes":5}],"sources":[{"id":"code","title":"Belgian road code — current consolidated rules","publisher":"Wegcode / Vias","url":"https://www.wegcode.be/nl/regelgeving/1975120109~hra8v386pu","note":"The consolidated 1975 code: priority, manoeuvres, speed, lights, stopping, parking and equipment."},{"id":"exam","title":"Theory exam for category B","publisher":"Flemish government","url":"https://www.vlaanderen.be/rijbewijs-b/theorie-examen-voor-rijbewijs-b","note":"Official exam format, pass mark, language support, eligibility and validity."},{"id":"licence","title":"Driving licence B","publisher":"Flemish government","url":"https://www.vlaanderen.be/rijbewijs-b","note":"Category B, provisional licences and the learning routes."},{"id":"centres","title":"Theory exam at Autoveiligheid","publisher":"Autoveiligheid","url":"https://www.autoveiligheid.be/rijbewijs/theorie-examen","note":"Geel’s exam operator: Dutch screen, Dutch then translated audio, and regular online appointments. Turnhout is listed as an inspection station."},{"id":"newcode","title":"Current code and the June 2027 transition","publisher":"Wegcode / Vias","url":"https://www.wegcode.be/nl/regelgeving/1975120109~hra8v386pu","note":"The consolidated current code explicitly states replacement on 1 June 2027 by federal and regional codes."},{"id":"degrees","title":"Third- and fourth-degree offences","publisher":"Wegcode / Vias","url":"https://www.wegcode.be/nl/perma/5yjza0ajqn/regulation_regulation","note":"The 30 September 2005 decree classifies offences; the simulator uses it to identify five-point mistakes."},{"id":"geel","title":"Geel driving-test centre","publisher":"Autoveiligheid","url":"https://www.autoveiligheid.be/rijbewijs/examencentra/examencentrum-geel","note":"Lammerdries 7, 2440 Geel. Official centre details and appointment links."}],"checked":"2026-10-01"};
window.DRIVE_QUESTIONS=[{"id":"q001","lesson":1,"text":"Which part of a public road is normally used by vehicles?","options":["The carriageway","Only the pavement","The entire road, without distinction"],"answer":0,"explanation":"The carriageway is the part normally used by vehicles. The public road can also include pavements, cycle paths and verges.","nl":"Welk deel van de openbare weg wordt normaal door voertuigen gebruikt?","nlOptions":["De rijbaan","Alleen het trottoir","De volledige weg, zonder onderscheid"],"major":false,"image":"road-anatomy.webp","severityReason":"Ordinary one-point practice question"},{"id":"q002","lesson":1,"text":"A road is privately owned but open to public traffic. Can road-traffic rules apply?","options":["Yes","No, never","Only if it has street lights"],"answer":0,"explanation":"Public accessibility matters; private ownership alone does not exclude the road from traffic rules.","nl":"Een weg is privé-eigendom maar staat open voor openbaar verkeer. Kunnen de verkeersregels er gelden?","nlOptions":["Ja","Nee, nooit","Alleen als er straatverlichting is"],"major":false,"image":null,"severityReason":"Ordinary one-point practice question"},{"id":"q003","lesson":1,"text":"On an ordinary two-way road, where should you normally drive?","options":["As far left as possible","As close to the right edge as appropriate","Always astride the centre line"],"answer":1,"explanation":"The normal position is near the right edge, while preserving safe clearance and respecting road markings.","nl":"Waar rijd je normaal op een gewone weg met verkeer in beide richtingen?","nlOptions":["Zo ver mogelijk links","Zo dicht mogelijk bij de rechterrand als verantwoord is","Altijd over de middenlijn"],"major":false,"image":null,"severityReason":"Ordinary one-point practice question"},{"id":"q004","lesson":2,"text":"You have a broken white line beside you and a solid line beyond it. May you cross the broken line if the move is safe?","options":["No, the further line always controls you","Yes, obey the line nearest you","Only after sounding the horn"],"answer":1,"explanation":"With combined solid and broken lines, follow the line nearest your vehicle. You still need a safe, lawful manoeuvre.","nl":"Naast jou ligt een onderbroken witte lijn, met daarnaast een doorlopende lijn. Mag je de onderbroken lijn veilig overschrijden?","nlOptions":["Nee, de verste lijn geldt altijd","Ja, de dichtstbijzijnde lijn geldt","Alleen na een claxonsignaal"],"major":false,"image":"lane-markings.webp","severityReason":"Ordinary one-point practice question"},{"id":"q005","lesson":2,"text":"Very slow traffic approaches a lane closure. Where should drivers use zipper merging?","options":["Far before the narrowing","Immediately before the narrowing","Only after the lane has already disappeared"],"answer":1,"explanation":"In very slow traffic, merge alternately immediately before the narrowing. This uses the available lanes efficiently.","nl":"Bij sterk vertraagd verkeer valt een rijstrook weg. Waar pas je ritsen toe?","nlOptions":["Ver vóór de versmalling","Vlak vóór de versmalling","Pas nadat de rijstrook al verdwenen is"],"major":false,"image":"zipper-merge.webp","severityReason":"Ordinary one-point practice question"},{"id":"q006","lesson":2,"text":"In roadworks, temporary orange markings conflict with white markings. Which do you follow?","options":["The white markings","The orange markings","Whichever lane is fastest"],"answer":1,"explanation":"Temporary orange markings take precedence over ordinary white markings.","nl":"Bij werken spreken tijdelijke oranje markeringen de witte markeringen tegen. Welke volg je?","nlOptions":["De witte markeringen","De oranje markeringen","De snelste rijstrook"],"major":false,"image":"temporary-road-markings.webp","severityReason":"Ordinary one-point practice question"},{"id":"q007","lesson":3,"text":"You drive a car in a signed cycle zone. May you overtake a cyclist?","options":["Yes, with a 1-metre gap","Yes, below 30 km/h","No"],"answer":2,"explanation":"Motor vehicles may not overtake cyclists in a cycle zone. The maximum is 30 km/h.","nl":"Je rijdt met een auto in een fietszone. Mag je een fietser inhalen?","nlOptions":["Ja, met één meter afstand","Ja, onder dertig kilometer per uur","Nee"],"major":false,"image":null,"severityReason":"Ordinary one-point practice question"},{"id":"q008","lesson":3,"text":"Does red surfacing alone prove that a strip is a legally reserved cycle path?","options":["Yes","No, check the signs and markings","Only outside a built-up area"],"answer":1,"explanation":"Colour alone is not the legal definition. A suggested cycle strip can be part of the carriageway.","nl":"Bewijst rode verharding op zichzelf dat een strook een voorbehouden fietspad is?","nlOptions":["Ja","Nee, kijk naar borden en markeringen","Alleen buiten de bebouwde kom"],"major":false,"image":null,"severityReason":"Ordinary one-point practice question"},{"id":"q009","lesson":3,"text":"A cyclist is riding along a cycle path that you must cross to turn right. What should you do?","options":["Turn first because you indicated","Give way to the cyclist","Sound the horn and turn"],"answer":1,"explanation":"When turning across a cycle path, give way to its users. An indicator does not give priority.","nl":"Een fietser rijdt op het fietspad dat je kruist om rechts af te slaan. Wat doe je?","nlOptions":["Eerst afslaan omdat je richting aangaf","Voorrang verlenen aan de fietser","Claxonneren en afslaan"],"major":true,"image":null,"severityReason":"Turning across cyclists: Article 19.4, third degree"},{"id":"q010","lesson":4,"text":"You miss your motorway exit. What is the correct action?","options":["Reverse along the shoulder","Stop in the exit lane","Continue to the next exit"],"answer":2,"explanation":"Never reverse or turn around on a motorway. Continue to the next exit.","nl":"Je mist je afrit op de autosnelweg. Wat doe je?","nlOptions":["Achteruitrijden op de pechstrook","Stoppen in de afritstrook","Doorrijden tot de volgende afrit"],"major":true,"image":null,"severityReason":"Reversing on a motorway: Article 21.4, fourth degree"},{"id":"q011","lesson":4,"text":"When entering a motorway, who normally has priority?","options":["Traffic already on the motorway","Traffic in the acceleration lane","The vehicle travelling faster"],"answer":0,"explanation":"The acceleration lane helps you find a safe gap; joining traffic must give way.","nl":"Wie heeft normaal voorrang wanneer je een autosnelweg oprijdt?","nlOptions":["Het verkeer dat al op de autosnelweg rijdt","Het verkeer op de invoegstrook","Het snelste voertuig"],"major":false,"image":null,"severityReason":"Ordinary one-point practice question"},{"id":"q012","lesson":4,"text":"A queue forms on a three-lane motorway. Where is the rescue corridor?","options":["Between the middle and right lanes","Between the leftmost lane and the lane beside it","On the central reservation"],"answer":1,"explanation":"The leftmost lane moves left; every other lane moves right. The corridor is between the leftmost lane and its neighbour.","nl":"Er ontstaat een file op een autosnelweg met drie rijstroken. Waar komt de reddingsstrook?","nlOptions":["Tussen de middelste en rechterrijstrook","Tussen de meest linkse rijstrook en de rijstrook ernaast","Op de middenberm"],"major":false,"image":"rescue-corridor.webp","severityReason":"Ordinary one-point practice question"},{"id":"q013","lesson":5,"text":"In Flanders, you drive a normal car on an ordinary road outside a built-up area. No speed signs apply. What is the normal maximum?","options":["50 km/h","70 km/h","90 km/h"],"answer":1,"explanation":"The Flemish default on ordinary roads outside a built-up area is 70 km/h. Specific road layouts or signs can change it.","nl":"Je rijdt in Vlaanderen met een gewone auto buiten de bebouwde kom op een gewone weg zonder snelheidsborden. Wat is de maximumsnelheid?","nlOptions":["Vijftig kilometer per uur","Zeventig kilometer per uur","Negentig kilometer per uur"],"major":true,"image":null,"severityReason":"Maximum permitted speed: five-point question under Flemish exam rules"},{"id":"q014","lesson":5,"text":"Outside a built-up area in Flanders, a road has two lanes each way separated only by paint. No signs apply. May you drive 120 km/h?","options":["Yes, it has four lanes","No, painted separation is not a physical central reservation","Yes, if traffic is light"],"answer":1,"explanation":"The 120 km/h road-layout exception needs physical separation. In this Flemish painted-separation case, the normal maximum is 70 km/h.","nl":"Een weg buiten de bebouwde kom in Vlaanderen heeft twee rijstroken per richting, alleen gescheiden door verf. Zonder borden mag je er honderdtwintig rijden?","nlOptions":["Ja, er zijn vier rijstroken","Nee, verf is geen fysieke middenberm","Ja, bij weinig verkeer"],"major":true,"image":null,"severityReason":"Maximum permitted speed: five-point question under Flemish exam rules"},{"id":"q015","lesson":5,"text":"You pass a junction inside a signed 30 km/h zone. Has the zone limit ended?","options":["Yes, every junction ends it","No, it continues until the zone-end sign","Only if the crossing road is wider"],"answer":1,"explanation":"A zone continues across junctions until its end sign.","nl":"Je passeert een kruispunt in een zone dertig. Eindigt de zonelimiet daar?","nlOptions":["Ja, elk kruispunt beëindigt ze","Nee, ze geldt tot het eindezonebord","Alleen als de kruisende weg breder is"],"major":true,"image":"school-zone.webp","severityReason":"Maximum permitted speed: five-point question under Flemish exam rules"},{"id":"q016","lesson":6,"text":"What is the usual maximum for a car in a built-up area in Flanders if no other limit applies?","options":["30 km/h","50 km/h","70 km/h"],"answer":1,"explanation":"Flanders uses a normal built-up-area maximum of 50 km/h. Brussels generally uses 30 km/h.","nl":"Wat is de gewone maximumsnelheid voor een auto binnen de bebouwde kom in Vlaanderen zonder andere beperking?","nlOptions":["Dertig kilometer per uur","Vijftig kilometer per uur","Zeventig kilometer per uur"],"major":true,"image":null,"severityReason":"Maximum permitted speed: five-point question under Flemish exam rules"},{"id":"q017","lesson":6,"text":"What is the maximum in a signed residential or home zone?","options":["20 km/h","30 km/h","50 km/h"],"answer":0,"explanation":"Residential/home zones have a 20 km/h maximum, and pedestrians may use the full road width.","nl":"Wat is de maximumsnelheid in een aangeduid erf of woonerf?","nlOptions":["Twintig kilometer per uur","Dertig kilometer per uur","Vijftig kilometer per uur"],"major":true,"image":"speed-20.webp","severityReason":"Maximum permitted speed: five-point question under Flemish exam rules"},{"id":"q018","lesson":6,"text":"Where may you park in a signed residential/home zone?","options":["Anywhere you leave 3 metres free","Only where markings or signs permit parking","On every pavement"],"answer":1,"explanation":"Parking in a residential/home zone is limited to places indicated by signs or markings.","nl":"Waar mag je parkeren in een aangeduid erf of woonerf?","nlOptions":["Overal waar drie meter vrij blijft","Alleen waar borden of markeringen parkeren toelaten","Op elk trottoir"],"major":false,"image":null,"severityReason":"Ordinary one-point practice question"},{"id":"q019","lesson":7,"text":"A pedestrian is clearly about to step onto an unsignalised zebra crossing. What should you do?","options":["Give way and stop if needed","Continue until they are in your lane","Sound the horn to warn them"],"answer":0,"explanation":"You must give way to pedestrians on or about to use an unsignalised zebra crossing.","nl":"Een voetganger wil duidelijk een zebrapad zonder verkeerslichten oversteken. Wat doe je?","nlOptions":["Voorrang verlenen en zo nodig stoppen","Doorrijden tot die in jouw rijstrook staat","Claxonneren om te waarschuwen"],"major":true,"image":null,"severityReason":"Zebra-crossing priority: Article 40.4.2, third degree"},{"id":"q020","lesson":7,"text":"A car has stopped just before an unsignalised zebra crossing. May you overtake it?","options":["Yes, if you see no pedestrian","No","Yes, below 20 km/h"],"answer":1,"explanation":"The stopped car may hide a pedestrian. Overtaking a vehicle approaching or stopped at such a crossing is prohibited.","nl":"Een auto staat stil voor een zebrapad zonder verkeerslichten. Mag je die inhalen?","nlOptions":["Ja, als je geen voetganger ziet","Nee","Ja, onder twintig kilometer per uur"],"major":true,"image":null,"severityReason":"Overtaking at a crossing: Article 17.2.5, third degree"},{"id":"q021","lesson":7,"text":"You turn right into a road a pedestrian is crossing. Who should wait?","options":["The pedestrian","You must give way","Whoever arrived last"],"answer":1,"explanation":"A turning driver must give way to pedestrians crossing the road being entered.","nl":"Je slaat rechts af naar een weg die een voetganger oversteekt. Wie moet wachten?","nlOptions":["De voetganger","Jij moet voorrang verlenen","Wie het laatst aankwam"],"major":true,"image":null,"severityReason":"Pedestrians when turning: Article 19.5, third degree"},{"id":"q022","lesson":8,"text":"May you hold your phone to read a message while waiting at a red light?","options":["Yes, because the car is not moving","No","Yes, if you keep one hand on the wheel"],"answer":1,"explanation":"Waiting at a red light is still driving. The rule covers holding, using or manipulating an unsecured mobile device with a screen.","nl":"Mag je je telefoon vasthouden om een bericht te lezen terwijl je voor rood wacht?","nlOptions":["Ja, de auto beweegt niet","Nee","Ja, met één hand aan het stuur"],"major":true,"image":null,"severityReason":"Unsecured screen device: Article 8.4, third degree"},{"id":"q023","lesson":8,"text":"At an equal junction, a cyclist approaches from your right. Does priority from the right apply to the cyclist?","options":["Yes","No, only to motor vehicles","Only if the cyclist dismounts"],"answer":0,"explanation":"A cyclist is a driver. Priority from the right is not reserved for cars.","nl":"Op een gelijkwaardig kruispunt komt een fietser van rechts. Geldt voorrang van rechts voor die fietser?","nlOptions":["Ja","Nee, alleen voor motorvoertuigen","Alleen als de fietser afstapt"],"major":false,"image":null,"severityReason":"Ordinary one-point practice question"},{"id":"q024","lesson":8,"text":"Someone is walking while pushing a bicycle. How are they treated by the traffic rules?","options":["As a pedestrian","As a car driver","As a cyclist who must remain on the cycle path"],"answer":0,"explanation":"A person pushing a bicycle is treated as a pedestrian.","nl":"Iemand loopt en duwt een fiets voort. Hoe wordt die persoon beschouwd?","nlOptions":["Als voetganger","Als autobestuurder","Als fietser die op het fietspad moet blijven"],"major":false,"image":null,"severityReason":"Ordinary one-point practice question"},{"id":"q025","lesson":9,"text":"What mass normally determines whether a vehicle falls within standard category B?","options":["Its current empty mass","Its maximum authorised mass","Only the passengers’ combined mass"],"answer":1,"explanation":"Category B generally uses maximum authorised mass, normally up to 3,500 kg, rather than the current empty weight.","nl":"Welke massa bepaalt normaal of een voertuig onder een gewoon rijbewijs B valt?","nlOptions":["De huidige lege massa","De maximaal toegelaten massa","Alleen de totale massa van de passagiers"],"major":false,"image":null,"severityReason":"Ordinary one-point practice question"},{"id":"q026","lesson":9,"text":"With a full standard B licence, a trailer has a MAM of 900 kg and the car a MAM of 2,400 kg. Is the combination within the standard B mass rule?","options":["Yes, total MAM is 3,300 kg","No, every trailer above 750 kg needs BE","No, total MAM exceeds 3,500 kg"],"answer":0,"explanation":"A trailer over 750 kg can be within B when the combination’s MAM does not exceed 3,500 kg. The car’s technical towing limit must also be respected.","nl":"Met een definitief rijbewijs B heeft de aanhangwagen een MTM van negenhonderd kilo en de auto vierentwintighonderd kilo. Valt dit binnen de gewone massaregel voor B?","nlOptions":["Ja, samen drieëndertighonderd kilo","Nee, boven zevenhonderdvijftig kilo is altijd BE nodig","Nee, samen meer dan vijfendertighonderd kilo"],"major":false,"image":null,"severityReason":"Ordinary one-point practice question"},{"id":"q027","lesson":9,"text":"Which item belongs in the required equipment of a normal Belgian-registered car?","options":["A warning triangle","A spare fuel tank","A tow rope in every case"],"answer":0,"explanation":"A warning triangle is required equipment; a normal Belgian car also needs a first-aid kit and an approved fire extinguisher.","nl":"Welk voorwerp behoort tot de verplichte uitrusting van een gewone Belgische auto?","nlOptions":["Een gevarendriehoek","Een extra brandstoftank","Altijd een sleepkabel"],"major":false,"image":"warning-triangle.webp","severityReason":"Ordinary one-point practice question"},{"id":"q028","lesson":10,"text":"A child under 18 is 1.20 metres tall. What is normally required in a car?","options":["Only an adult seat belt","A suitable child restraint","No restraint in a rear seat"],"answer":1,"explanation":"A child under 18 shorter than 1.35 m normally needs an appropriate child restraint.","nl":"Een kind jonger dan achttien is één meter twintig groot. Wat is normaal verplicht in een auto?","nlOptions":["Alleen een volwassenengordel","Een geschikt kinderbeveiligingssysteem","Geen beveiliging achterin"],"major":true,"image":null,"severityReason":"Child restraint: Article 35.1.1, third degree"},{"id":"q029","lesson":10,"text":"May a rear-facing child seat be used in front of an active frontal airbag?","options":["Yes, at low speed","No","Yes, if the child is asleep"],"answer":1,"explanation":"A rear-facing seat must not be used in front of an active frontal airbag. Deactivate it or use a suitable rear-seat position.","nl":"Mag een achterwaarts gericht kinderzitje voor een actieve frontale airbag worden gebruikt?","nlOptions":["Ja, bij lage snelheid","Nee","Ja, als het kind slaapt"],"major":true,"image":null,"severityReason":"Rear-facing seat and active airbag: Article 35.1.1, third degree"},{"id":"q030","lesson":10,"text":"May a ladder carried by a passenger car project beyond the front of the car?","options":["Yes, up to 1 metre","No","Yes, if tied down"],"answer":1,"explanation":"A passenger-car load must not project at the front. Rear projections have separate limits and marking requirements.","nl":"Mag een ladder op een personenauto vooraan voorbij de auto uitsteken?","nlOptions":["Ja, tot één meter","Nee","Ja, als ze vastgebonden is"],"major":false,"image":null,"severityReason":"Ordinary one-point practice question"},{"id":"q031","lesson":11,"text":"In fog, visibility is 80 metres. What is required for the rear fog light?","options":["Use it","Keep it off unless it is night","Use only hazard lights"],"answer":0,"explanation":"Rear fog lights must be used in fog or snowfall with visibility below 100 m, and in heavy rain.","nl":"Bij mist is de zichtbaarheid tachtig meter. Wat moet je doen met het mistachterlicht?","nlOptions":["Inschakelen","Uit laten behalve in de nacht","Alleen de alarmlichten gebruiken"],"major":false,"image":null,"severityReason":"Ordinary one-point practice question"},{"id":"q032","lesson":11,"text":"You enter a tunnel during the day. Should you rely on daytime running lights alone?","options":["Yes, always","No, use proper dipped headlights","Only if the tunnel is busy"],"answer":1,"explanation":"Use dipped headlights in a tunnel. DRLs may not illuminate the rear of your car.","nl":"Je rijdt overdag een tunnel in. Volstaan alleen dagrijlichten?","nlOptions":["Ja, altijd","Nee, gebruik de dimlichten","Alleen als het druk is"],"major":false,"image":"tunnel.webp","severityReason":"Ordinary one-point practice question"},{"id":"q033","lesson":11,"text":"Does indicating before a lane change give you priority?","options":["Yes","No","Only on a motorway"],"answer":1,"explanation":"An indicator communicates your intention. A lane change is a manoeuvre, and you must give way.","nl":"Geeft je richtingaanwijzer je voorrang bij het veranderen van rijstrook?","nlOptions":["Ja","Nee","Alleen op een autosnelweg"],"major":false,"image":null,"severityReason":"Ordinary one-point practice question"},{"id":"q034","lesson":12,"text":"On a motorway, a 90 km/h sign applies. What is the maximum for your normal car?","options":["120 km/h","90 km/h","130 km/h"],"answer":1,"explanation":"The posted lower limit overrides the normal motorway maximum.","nl":"Op de autosnelweg geldt een bord van negentig kilometer per uur. Wat is de maximumsnelheid voor je gewone auto?","nlOptions":["Honderdtwintig kilometer per uur","Negentig kilometer per uur","Honderddertig kilometer per uur"],"major":true,"image":null,"severityReason":"Maximum permitted speed: five-point question under Flemish exam rules"},{"id":"q035","lesson":12,"text":"The posted limit is 70 km/h, but dense fog greatly reduces your view. Should you maintain 70?","options":["Yes, the sign requires it","No, adapt speed to visibility","Yes, with high beam"],"answer":1,"explanation":"A maximum is not a target. You must be able to stop within your visible, clear distance.","nl":"De limiet is zeventig maar dichte mist beperkt het zicht. Moet je zeventig blijven rijden?","nlOptions":["Ja, het bord verplicht dat","Nee, pas je snelheid aan het zicht aan","Ja, met grootlichten"],"major":false,"image":null,"severityReason":"Ordinary one-point practice question"},{"id":"q036","lesson":12,"text":"What is the normal speed limit in a built-up area in Brussels when no different limit is signed?","options":["30 km/h","50 km/h","70 km/h"],"answer":0,"explanation":"Brussels uses 30 km/h in built-up areas. Outside them, ordinary-road and motorway defaults differ.","nl":"Wat is de gewone snelheidslimiet binnen de bebouwde kom in Brussel zonder andere limiet?","nlOptions":["Dertig kilometer per uur","Vijftig kilometer per uur","Zeventig kilometer per uur"],"major":true,"image":null,"severityReason":"Maximum permitted speed: five-point question under Flemish exam rules"},{"id":"q037","lesson":13,"text":"What makes up stopping distance?","options":["Only braking distance","Reaction distance plus braking distance","Only the distance travelled in one second"],"answer":1,"explanation":"The car moves during your reaction time, then continues moving while braking. Both distances form the stop.","nl":"Waaruit bestaat de stopafstand?","nlOptions":["Alleen de remafstand","Reactieafstand plus remafstand","Alleen de afstand van één seconde"],"major":false,"image":null,"severityReason":"Ordinary one-point practice question"},{"id":"q038","lesson":13,"text":"Under the same grip conditions, doubling speed does what to braking distance approximately?","options":["Halves it","Doubles it","Quadruples it"],"answer":2,"explanation":"Braking distance grows approximately with the square of speed, so doubling speed roughly quadruples it.","nl":"Wat gebeurt ongeveer met de remafstand als je de snelheid verdubbelt bij dezelfde grip?","nlOptions":["Ze halveert","Ze verdubbelt","Ze verviervoudigt"],"major":false,"image":null,"severityReason":"Ordinary one-point practice question"},{"id":"q039","lesson":13,"text":"On a wet road, what should you do with your following gap?","options":["Increase it","Keep exactly the same gap","Reduce it so nobody merges"],"answer":0,"explanation":"Wet conditions reduce grip and usually increase braking distance, so allow a larger gap.","nl":"Wat doe je met je volgafstand op een natte weg?","nlOptions":["Vergroten","Exact gelijk houden","Verkleinen zodat niemand invoegt"],"major":false,"image":null,"severityReason":"Ordinary one-point practice question"},{"id":"q040","lesson":14,"text":"A parked van blocks your side of a narrow two-way road. An oncoming car is close. What should you normally do?","options":["Go around first","Give way before passing the obstacle","Use the pavement"],"answer":1,"explanation":"When the obstacle is on your side, normally yield to oncoming traffic and go around only when safe.","nl":"Een geparkeerde bestelwagen blokkeert jouw kant van een smalle tweerichtingsweg. Er nadert een auto. Wat doe je normaal?","nlOptions":["Eerst voorbijrijden","Voorrang verlenen voor je het obstakel voorbijrijdt","Het trottoir gebruiken"],"major":true,"image":null,"severityReason":"Meeting traffic around an obstacle: Article 15.2, third degree"},{"id":"q041","lesson":14,"text":"You have priority at a narrow section, but an oncoming vehicle is already in it. What should you do?","options":["Enter and force it to reverse","Wait and avoid a collision","Sound the horn continuously"],"answer":1,"explanation":"Priority never removes the obligation to avoid danger. Do not force your way into an occupied narrow section.","nl":"Je hebt voorrang aan een versmalling, maar een tegenligger is er al in. Wat doe je?","nlOptions":["Inrijden en hem dwingen achteruit te rijden","Wachten en een aanrijding vermijden","Ononderbroken claxonneren"],"major":false,"image":null,"severityReason":"Ordinary one-point practice question"},{"id":"q042","lesson":14,"text":"To pass an oncoming vehicle, may you force a cyclist onto the verge?","options":["Yes, if you indicate","No","Only outside town"],"answer":1,"explanation":"You must leave safe clearance and protect vulnerable users. Slow or stop when there is insufficient space.","nl":"Mag je een fietser op de berm dwingen om een tegenligger te kruisen?","nlOptions":["Ja, als je richting aangeeft","Nee","Alleen buiten de bebouwde kom"],"major":true,"image":null,"severityReason":"Endangering a cyclist: Article 40ter, third degree"},{"id":"q043","lesson":15,"text":"What is the minimum lateral clearance when passing a cyclist outside a built-up area?","options":["0.5 metre","1 metre","1.5 metres"],"answer":2,"explanation":"Outside a built-up area, leave at least 1.5 m; within a built-up area, at least 1 m.","nl":"Wat is de minimale zijdelingse afstand bij het voorbijrijden van een fietser buiten de bebouwde kom?","nlOptions":["Een halve meter","Eén meter","Anderhalve meter"],"major":true,"image":"passing-cyclist.webp","severityReason":"Cyclist lateral clearance: Article 40ter, third degree"},{"id":"q044","lesson":15,"text":"The driver ahead clearly signals and positions to turn left. May you pass on the right if there is enough lawful space?","options":["Yes","No, there are no exceptions","Only using the cycle path"],"answer":0,"explanation":"This is a specific exception to the normal left-side overtaking rule. The available space must be lawful and safe.","nl":"De bestuurder voor je geeft duidelijk links aan en stelt zich op om links af te slaan. Mag je rechts voorbij als er voldoende toegelaten ruimte is?","nlOptions":["Ja","Nee, er bestaan geen uitzonderingen","Alleen via het fietspad"],"major":false,"image":null,"severityReason":"Ordinary one-point practice question"},{"id":"q045","lesson":15,"text":"Before overtaking, you notice another vehicle already overtaking you. What should you do?","options":["Start anyway","Wait and let it complete its pass","Accelerate to block it"],"answer":1,"explanation":"Check behind before moving left. Do not begin an overtaking manoeuvre when someone is already overtaking you.","nl":"Voor je inhaalt zie je dat een ander voertuig jou al inhaalt. Wat doe je?","nlOptions":["Toch beginnen","Wachten en het laten voorbijrijden","Versnellen om het te blokkeren"],"major":false,"image":null,"severityReason":"Ordinary one-point practice question"},{"id":"q046","lesson":16,"text":"May you cross a continuous white line to overtake a slow car?","options":["Yes, if the road is empty","No","Yes, after flashing your lights"],"answer":1,"explanation":"Crossing a continuous white line to overtake is prohibited. Wait for a legal opportunity.","nl":"Mag je een doorlopende witte lijn overschrijden om een trage auto in te halen?","nlOptions":["Ja, als de weg leeg is","Nee","Ja, na een lichtsignaal"],"major":true,"image":null,"severityReason":"Crossing a continuous white line: Article 72.2, third degree"},{"id":"q047","lesson":16,"text":"Someone is overtaking your car. May you accelerate?","options":["Yes, to finish sooner","No","Only if they are too slow"],"answer":1,"explanation":"A driver being overtaken must keep right as appropriate and must not accelerate.","nl":"Iemand haalt je auto in. Mag je versnellen?","nlOptions":["Ja, om sneller klaar te zijn","Nee","Alleen als die te traag is"],"major":true,"image":null,"severityReason":"Accelerating while being overtaken: Article 16.7, third degree"},{"id":"q048","lesson":16,"text":"You cannot see beyond a blind bend on an ordinary two-way road. Should you start overtaking a car?","options":["Yes, quickly","No","Yes, with the horn"],"answer":1,"explanation":"You need sufficient visibility and space to complete a safe overtake. A blind bend removes that assurance.","nl":"Je ziet niet voorbij een onoverzichtelijke bocht op een gewone tweerichtingsweg. Begin je een auto in te halen?","nlOptions":["Ja, snel","Nee","Ja, met de claxon"],"major":true,"image":null,"severityReason":"Overtaking a car at a blind bend: Article 17.2.3, fourth degree"},{"id":"q049","lesson":17,"text":"A police officer instructs you to proceed, but the traffic light is red. Which instruction takes priority?","options":["The traffic light","The officer’s instruction","The nearest road sign"],"answer":1,"explanation":"An authorised person’s instruction takes precedence over traffic lights, signs and general rules.","nl":"Een politieagent beveelt door te rijden maar het verkeerslicht is rood. Wat heeft voorrang?","nlOptions":["Het verkeerslicht","Het bevel van de agent","Het dichtstbijzijnde verkeersbord"],"major":true,"image":null,"severityReason":"Authorised person’s instruction: Article 4.1, third degree"},{"id":"q050","lesson":17,"text":"A priority vehicle approaches with its special audible warning. What must you do?","options":["Immediately clear a safe passage and give way","Keep going unless it touches your lane","Follow closely behind it"],"answer":0,"explanation":"Make passage immediately, give way and stop if necessary, without creating new danger.","nl":"Een prioritair voertuig nadert met zijn speciaal geluidssignaal. Wat moet je doen?","nlOptions":["Meteen veilig ruimte maken en voorrang verlenen","Doorrijden tenzij het jouw rijstrook raakt","Er vlak achter rijden"],"major":true,"image":null,"severityReason":"Emergency vehicle passage: Article 38, third degree"},{"id":"q051","lesson":17,"text":"May you follow an ambulance through a rescue corridor to avoid the queue?","options":["Yes, if you leave a gap","No","Only with hazard lights"],"answer":1,"explanation":"The rescue corridor is for emergency access, not an extra passing lane.","nl":"Mag je achter een ambulance door de reddingsstrook rijden om de file te vermijden?","nlOptions":["Ja, met afstand","Nee","Alleen met alarmlichten"],"major":false,"image":"rescue-corridor.webp","severityReason":"Ordinary one-point practice question"},{"id":"q052","lesson":18,"text":"A steady amber light appears and you can stop safely before the line. What should you do?","options":["Stop","Accelerate","Continue because amber always allows passage"],"answer":0,"explanation":"Stop for steady amber unless you are too close to stop safely.","nl":"Het licht wordt vast oranje en je kunt veilig voor de streep stoppen. Wat doe je?","nlOptions":["Stoppen","Versnellen","Doorrijden want oranje laat altijd doorgang toe"],"major":false,"image":null,"severityReason":"Ordinary one-point practice question"},{"id":"q053","lesson":18,"text":"You face a red traffic light. May you cross the stop line because the junction looks empty?","options":["Yes","No","Only late at night"],"answer":1,"explanation":"A red light prohibits passing the stop line. An apparently empty junction does not change it.","nl":"Het verkeerslicht is rood. Mag je de stopstreep voorbij omdat het kruispunt leeg lijkt?","nlOptions":["Ja","Nee","Alleen laat in de nacht"],"major":true,"image":null,"severityReason":"Passing a red light: Article 61.1.1, third degree"},{"id":"q054","lesson":18,"text":"The lights at a junction flash amber. Give-way signs are present. Which rule applies?","options":["The signs, with extra caution","You automatically have priority","The largest vehicle goes first"],"answer":0,"explanation":"Flashing amber warns you to be careful. Priority signs still apply.","nl":"De verkeerslichten knipperen oranje en er staan voorrangsborden. Welke regel geldt?","nlOptions":["De borden, met extra voorzichtigheid","Je hebt automatisch voorrang","Het grootste voertuig gaat eerst"],"major":false,"image":null,"severityReason":"Ordinary one-point practice question"},{"id":"q055","lesson":19,"text":"At a STOP sign, no traffic is visible. Must you still come to a complete stop?","options":["Yes","No, slowing down is enough","Only if a pedestrian is present"],"answer":0,"explanation":"STOP requires a complete stop, then giving way. This differs from a give-way sign.","nl":"Aan een STOP-bord is geen verkeer te zien. Moet je volledig stoppen?","nlOptions":["Ja","Nee, vertragen volstaat","Alleen als er een voetganger is"],"major":false,"image":"stop-junction.webp","severityReason":"Ordinary one-point practice question"},{"id":"q056","lesson":19,"text":"What does this yellow diamond sign indicate?","options":["End of all speed restrictions","A priority road","A compulsory left turn"],"answer":1,"explanation":"The yellow diamond identifies a priority road. It does not set a speed limit.","nl":"Wat betekent dit gele ruitvormige bord?","nlOptions":["Einde van alle snelheidsbeperkingen","Een voorrangsweg","Verplicht links afslaan"],"major":false,"image":"priority-road-sign.webp","severityReason":"Ordinary one-point practice question"},{"id":"q057","lesson":19,"text":"You leave a roundabout. Which indicator should you use?","options":["Right","Left","None in every case"],"answer":0,"explanation":"Indicate right before exiting and check for pedestrians and cyclists.","nl":"Je verlaat een rotonde. Welke richtingaanwijzer gebruik je?","nlOptions":["Rechts","Links","Nooit een richtingaanwijzer"],"major":false,"image":null,"severityReason":"Ordinary one-point practice question"},{"id":"q058","lesson":20,"text":"In this diagram, there are no signals or priority signs. You drive the purple car. Who normally goes first?","options":["The purple car","The red car coming from the right","The larger car"],"answer":1,"explanation":"The red car approaches from the purple driver’s right. Priority from the right applies.","nl":"Er zijn geen lichten of voorrangsborden. Jij rijdt met de paarse auto. Wie gaat normaal eerst?","nlOptions":["De paarse auto","De rode auto die van rechts komt","De grootste auto"],"major":false,"image":"priority-from-right.webp","severityReason":"Ordinary one-point practice question"},{"id":"q059","lesson":20,"text":"At an equal junction, a driver from your right has stopped. Have they automatically lost priority?","options":["Yes","No","Only if stopped for 3 seconds"],"answer":1,"explanation":"Stopping does not automatically remove priority from the right. Do not assume their hesitation gives you priority.","nl":"Op een gelijkwaardig kruispunt is de bestuurder rechts gestopt. Verliest die automatisch voorrang?","nlOptions":["Ja","Nee","Alleen na drie seconden"],"major":false,"image":null,"severityReason":"Ordinary one-point practice question"},{"id":"q060","lesson":20,"text":"You reverse out of a parking space. Who must you give way to?","options":["Only cars coming from the right","All other road users affected by your manoeuvre","Nobody if you indicate"],"answer":1,"explanation":"Reversing is a manoeuvre. The driver performing it must give way to other road users.","nl":"Je rijdt achteruit uit een parkeerplaats. Aan wie moet je voorrang verlenen?","nlOptions":["Alleen auto’s van rechts","Alle andere weggebruikers die bij je manoeuvre betrokken zijn","Niemand als je richting aangeeft"],"major":false,"image":null,"severityReason":"Ordinary one-point practice question"},{"id":"q061","lesson":21,"text":"You turn left while an oncoming car continues straight. Who should go first?","options":["You","The oncoming car","Whoever signals first"],"answer":1,"explanation":"A left-turning driver gives way to oncoming traffic continuing straight or turning right.","nl":"Je slaat links af terwijl een tegenligger rechtdoor rijdt. Wie gaat eerst?","nlOptions":["Jij","De tegenligger","Wie eerst richting aangeeft"],"major":true,"image":null,"severityReason":"Left-turn priority: Article 19.3.3, third degree"},{"id":"q062","lesson":21,"text":"Before turning right across a cycle path, what check is essential?","options":["Only the centre mirror","Mirrors and the right blind spot for cyclists","Only the traffic light ahead"],"answer":1,"explanation":"Cyclists can be beside or behind you. Check mirrors and the blind spot, then give way when crossing their path.","nl":"Welke controle is essentieel voor je rechts over een fietspad afslaat?","nlOptions":["Alleen de binnenspiegel","Spiegels en de rechterdodehoek voor fietsers","Alleen het verkeerslicht voor je"],"major":false,"image":null,"severityReason":"Ordinary one-point practice question"},{"id":"q063","lesson":21,"text":"On a two-way road, how should you normally prepare for a left turn?","options":["Move toward the centre without entering the oncoming side","Move to the right pavement","Drive on the oncoming lane early"],"answer":0,"explanation":"Position toward the centre while remaining on your lawful side, signal and give way as required.","nl":"Hoe stel je je normaal op voor links afslaan op een tweerichtingsweg?","nlOptions":["Naar het midden zonder de tegenrichting te gebruiken","Naar het rechtertrottoir","Vroeg op de rijstrook van tegenliggers"],"major":false,"image":null,"severityReason":"Ordinary one-point practice question"},{"id":"q064","lesson":22,"text":"A railway signal flashes red but the barrier is still up. May you cross?","options":["Yes, until the barrier starts moving","No","Yes, if you see no train"],"answer":1,"explanation":"Red flashing signals already require stopping. Do not wait for the barrier to lower.","nl":"Het spoorwegsignaal knippert rood maar de slagboom staat nog omhoog. Mag je oversteken?","nlOptions":["Ja, tot de slagboom beweegt","Nee","Ja, als je geen trein ziet"],"major":true,"image":"level-crossing.webp","severityReason":"Red railway signal: Article 20.3, fourth degree"},{"id":"q065","lesson":22,"text":"A tram approaches from your left. No officer or traffic light changes the rule. Who normally has priority?","options":["You, because the tram is on the left","The tram","The faster vehicle"],"answer":1,"explanation":"Rail vehicles normally have priority over other road users, including when approaching from the left.","nl":"Een tram komt van links. Geen agent of verkeerslicht wijzigt de regel. Wie heeft normaal voorrang?","nlOptions":["Jij, want de tram komt van links","De tram","Het snelste voertuig"],"major":false,"image":null,"severityReason":"Ordinary one-point practice question"},{"id":"q066","lesson":22,"text":"In a built-up area, a bus signals to leave its stop. What should you do?","options":["Let it pull out, stopping if needed","Accelerate past before it moves","Ignore it unless it is on your right"],"answer":0,"explanation":"In a built-up area, allow a signalling bus or trolleybus to leave its stop.","nl":"Binnen de bebouwde kom geeft een bus richting aan om zijn halte te verlaten. Wat doe je?","nlOptions":["Laten vertrekken en zo nodig stoppen","Versnellen en er nog voorbijrijden","Negeren tenzij hij rechts staat"],"major":false,"image":"bus-stop.webp","severityReason":"Ordinary one-point practice question"},{"id":"q067","lesson":23,"text":"A no-entry sign has a plate excepting bicycles. May you enter in a car?","options":["Yes, at cycle speed","No","Yes, if no cyclists are present"],"answer":1,"explanation":"An exception for bicycles does not apply to a car.","nl":"Onder een verboden-inrijbord staat een uitzondering voor fietsen. Mag je met een auto inrijden?","nlOptions":["Ja, aan fietssnelheid","Nee","Ja, als er geen fietsers zijn"],"major":true,"image":null,"severityReason":"No-entry sign C1: Articles 5 and 68.3, third degree"},{"id":"q068","lesson":23,"text":"A one-way road permits cyclists in the opposite direction. Should you check for them before turning?","options":["Yes","No, one-way means no oncoming users","Only at night"],"answer":0,"explanation":"A one-way rule for cars can permit contraflow cycling. Read the plates and check for lawful oncoming cyclists.","nl":"Een eenrichtingsweg laat fietsers in tegenrichting toe. Moet je daarop letten voor je afslaat?","nlOptions":["Ja","Nee, eenrichtingsverkeer betekent geen tegenliggers","Alleen in de nacht"],"major":false,"image":null,"severityReason":"Ordinary one-point practice question"},{"id":"q069","lesson":23,"text":"A height-limit sign shows 2.5 metres. Your roof load makes the car 2.6 metres high. May you enter?","options":["Yes, the sign excludes the load","No","Yes, if the load is soft"],"answer":1,"explanation":"Height restrictions include the load. Your total height exceeds the limit.","nl":"Een hoogtebeperking is twee meter vijftig. Met daklading is je auto twee meter zestig hoog. Mag je inrijden?","nlOptions":["Ja, de lading telt niet","Nee","Ja, als de lading zacht is"],"major":false,"image":null,"severityReason":"Ordinary one-point practice question"},{"id":"q070","lesson":24,"text":"What must a car do at the pictured mandatory-direction sign?","options":["Go straight","Turn left if clear","Choose any direction because bicycles are excepted"],"answer":0,"explanation":"The blue arrow requires straight ahead. The supplementary cycle/moped exception does not exempt a car.","nl":"Wat moet een auto doen aan dit gebodsbord?","nlOptions":["Rechtdoor rijden","Links afslaan als het vrij is","Elke richting kiezen omdat fietsen uitgezonderd zijn"],"major":false,"image":"mandatory-straight.webp","severityReason":"Ordinary one-point practice question"},{"id":"q071","lesson":24,"text":"You discover too late that you are in a straight-ahead-only lane. What is safest and legal?","options":["Turn anyway","Follow the lane and find another route","Reverse to change lanes"],"answer":1,"explanation":"Follow the lawful lane direction rather than making a sudden prohibited move.","nl":"Je merkt te laat dat je in een rijstrook uitsluitend voor rechtdoor staat. Wat is veilig en wettig?","nlOptions":["Toch afslaan","De rijstrook volgen en een andere route zoeken","Achteruitrijden om van strook te veranderen"],"major":false,"image":null,"severityReason":"Ordinary one-point practice question"},{"id":"q072","lesson":24,"text":"A sign requires a right turn. Does that give you priority over pedestrians crossing the road you enter?","options":["Yes","No","Only if you signal"],"answer":1,"explanation":"A mandatory direction does not override the turning driver’s duty to give way to crossing pedestrians.","nl":"Een bord verplicht rechts af te slaan. Geeft dat voorrang op voetgangers die de weg oversteken waar je inrijdt?","nlOptions":["Ja","Nee","Alleen met richtingaanwijzer"],"major":true,"image":null,"severityReason":"Pedestrians when turning: Article 19.5, third degree"},{"id":"q073","lesson":25,"text":"You sit in your car waiting for a friend to arrive. Legally, is this stopping for boarding or parking?","options":["Parking","Stopping, because you stay inside","Neither if the engine runs"],"answer":0,"explanation":"Waiting for someone to arrive is parking. Stopping is only the time necessary for actual boarding or loading.","nl":"Je zit in de auto en wacht tot een vriend aankomt. Is dat stilstaan om in te stappen of parkeren?","nlOptions":["Parkeren","Stilstaan, want je blijft binnen","Geen van beide als de motor draait"],"major":false,"image":null,"severityReason":"Ordinary one-point practice question"},{"id":"q074","lesson":25,"text":"May you briefly stop on a cycle path to drop off a passenger?","options":["Yes, with hazard lights","No","Yes, if no cyclist is visible"],"answer":1,"explanation":"Both stopping and parking on a cycle path are prohibited. Hazard lights do not create an exception.","nl":"Mag je even op een fietspad stilstaan om iemand af te zetten?","nlOptions":["Ja, met alarmlichten","Nee","Ja, als je geen fietser ziet"],"major":false,"image":"parking-on-cycle-lane.webp","severityReason":"Ordinary one-point practice question"},{"id":"q075","lesson":25,"text":"On the carriageway, how much distance must you normally leave before a pedestrian crossing when stopping or parking?","options":["At least 1 metre","At least 5 metres","No distance if your car is small"],"answer":1,"explanation":"Stopping and parking on the carriageway are prohibited within 5 m before the crossing. The crossing itself must always stay clear.","nl":"Hoeveel afstand moet je op de rijbaan normaal vóór een zebrapad houden bij stilstaan of parkeren?","nlOptions":["Minstens één meter","Minstens vijf meter","Geen afstand bij een kleine auto"],"major":false,"image":null,"severityReason":"Ordinary one-point practice question"},{"id":"q076","lesson":26,"text":"What does the pictured sign prohibit?","options":["Parking only","Both stopping and parking","All traffic"],"answer":0,"explanation":"One diagonal red bar prohibits parking. Genuine boarding or loading can be allowed if no other stopping prohibition applies.","nl":"Wat verbiedt dit bord?","nlOptions":["Alleen parkeren","Stilstaan en parkeren","Alle verkeer"],"major":false,"image":"no-parking-sign.webp","severityReason":"Ordinary one-point practice question"},{"id":"q077","lesson":26,"text":"What does this red-and-blue cross sign prohibit?","options":["Only parking overnight","Both stopping and parking","Only loading goods"],"answer":1,"explanation":"The cross sign prohibits both stopping and parking.","nl":"Wat verbiedt dit rood-blauwe bord met een kruis?","nlOptions":["Alleen ’s nachts parkeren","Stilstaan en parkeren","Alleen goederen laden"],"major":false,"image":"no-stopping-sign.webp","severityReason":"Ordinary one-point practice question"},{"id":"q078","lesson":26,"text":"A broken yellow line runs along the carriageway edge. May you park beside it?","options":["Yes, if you stay in the car","No","Only for 10 minutes"],"answer":1,"explanation":"A broken yellow edge line prohibits parking along it. It does not automatically prohibit genuine stopping, but other restrictions may apply.","nl":"Een gele onderbroken lijn ligt langs de rand van de rijbaan. Mag je ernaast parkeren?","nlOptions":["Ja, als je binnen blijft","Nee","Alleen tien minuten"],"major":false,"image":"yellow-parking-line.webp","severityReason":"Ordinary one-point practice question"},{"id":"q079","lesson":27,"text":"You arrive at 10:10 in a standard blue zone. What time should you set on the disc?","options":["10:00","10:30","11:00"],"answer":1,"explanation":"Set the next half-hour mark following arrival: 10:10 becomes 10:30. The normal 2-hour period then runs to 12:30 unless signs differ.","nl":"Je komt om tien uur tien aan in een gewone blauwe zone. Op welke tijd zet je de parkeerschijf?","nlOptions":["Tien uur","Tien uur dertig","Elf uur"],"major":false,"image":"parking-disc.webp","severityReason":"Ordinary one-point practice question"},{"id":"q080","lesson":27,"text":"Your blue-zone parking time has expired. May you reset the disc without moving the car?","options":["Yes","No","Only once"],"answer":1,"explanation":"You must move the vehicle; resetting the disc while staying is prohibited.","nl":"Je parkeertijd in de blauwe zone is verlopen. Mag je de schijf opnieuw instellen zonder de auto te verplaatsen?","nlOptions":["Ja","Nee","Slechts één keer"],"major":false,"image":null,"severityReason":"Ordinary one-point practice question"},{"id":"q081","lesson":27,"text":"In a standard blue zone with no different posted hours, is the disc normally required on Saturday at 11:00?","options":["Yes","No, Saturday is always excluded","Only after 18:00"],"answer":0,"explanation":"Standard blue-zone hours are working days, normally Monday to Saturday, 09:00–18:00. Check signs for local differences and public holidays.","nl":"Is in een gewone blauwe zone zonder afwijkende uren normaal een schijf nodig op zaterdag om elf uur?","nlOptions":["Ja","Nee, zaterdag is altijd uitgesloten","Alleen na achttien uur"],"major":false,"image":"blue-zone.webp","severityReason":"Ordinary one-point practice question"},{"id":"q082","lesson":28,"text":"For an ordinary car driver, at what blood-alcohol level does the usual punishable threshold begin?","options":["0.5 g/l","1.0 g/l","1.5 g/l"],"answer":0,"explanation":"The ordinary threshold is 0.5 g/l blood, equivalent to 0.5 per mille, or 0.22 mg/l breath. Some professional drivers have a lower threshold.","nl":"Vanaf welk alcoholgehalte in het bloed begint de gewone strafbare grens voor een autobestuurder?","nlOptions":["Nul komma vijf gram per liter","Eén gram per liter","Eén komma vijf gram per liter"],"major":false,"image":"breathalyser.webp","severityReason":"Ordinary one-point practice question"},{"id":"q083","lesson":28,"text":"Which reliably lowers the amount of alcohol in your body?","options":["Coffee","A cold shower","Time"],"answer":2,"explanation":"Only time allows your body to eliminate alcohol. Coffee and cold showers do not make you sober.","nl":"Wat verlaagt betrouwbaar de hoeveelheid alcohol in je lichaam?","nlOptions":["Koffie","Een koude douche","Tijd"],"major":false,"image":null,"severityReason":"Ordinary one-point practice question"},{"id":"q084","lesson":28,"text":"A prescription medicine makes you drowsy. Is it automatically safe to drive because it was prescribed?","options":["Yes","No","Yes, on short trips"],"answer":1,"explanation":"Prescription status does not guarantee driving fitness. Read warnings and consult a pharmacist.","nl":"Een voorgeschreven geneesmiddel maakt je slaperig. Mag je automatisch veilig rijden omdat het is voorgeschreven?","nlOptions":["Ja","Nee","Ja, bij korte ritten"],"major":false,"image":null,"severityReason":"Ordinary one-point practice question"},{"id":"q085","lesson":29,"text":"When safely placing a warning triangle behind a breakdown on a motorway, what is the minimum normal distance?","options":["10 metres","30 metres","100 metres"],"answer":2,"explanation":"Normally at least 100 m on a motorway, compared with at least 30 m on an ordinary road. Never expose yourself to traffic to place it.","nl":"Wat is normaal de minimale afstand voor een veilig geplaatste gevarendriehoek achter een defect voertuig op de autosnelweg?","nlOptions":["Tien meter","Dertig meter","Honderd meter"],"major":false,"image":"warning-triangle.webp","severityReason":"Ordinary one-point practice question"},{"id":"q086","lesson":29,"text":"There are injured people after a collision. Which emergency number should you call?","options":["112","Only your insurer","The parking operator"],"answer":0,"explanation":"Call 112, give the exact location, casualties and hazards, and follow the operator’s instructions.","nl":"Er zijn gewonden na een ongeval. Welk noodnummer bel je?","nlOptions":["Honderdtwaalf","Alleen je verzekeraar","De parkeerbeheerder"],"major":false,"image":null,"severityReason":"Ordinary one-point practice question"},{"id":"q087","lesson":29,"text":"You break down on a motorway. Where should occupants wait when it is safe to reach it?","options":["In front of the car","Behind the safety barrier, away from traffic","On the shoulder beside the car"],"answer":1,"explanation":"Get people away from live traffic and behind the barrier when safely possible. Use a reflective vest and warn others without putting yourself at risk.","nl":"Je krijgt pech op de autosnelweg. Waar wachten inzittenden als ze er veilig kunnen komen?","nlOptions":["Voor de auto","Achter de vangrail, weg van het verkeer","Op de pechstrook naast de auto"],"major":false,"image":"reflective-vest.webp","severityReason":"Ordinary one-point practice question"},{"id":"q088","lesson":30,"text":"Which driving style usually reduces fuel use and risk?","options":["Repeated hard acceleration and braking","Anticipating traffic and easing off early","Tailgating to reduce air resistance"],"answer":1,"explanation":"Anticipation and smooth changes in speed reduce unnecessary acceleration and sudden braking.","nl":"Welke rijstijl vermindert meestal verbruik en risico?","nlOptions":["Herhaald hard optrekken en remmen","Vooruitkijken en tijdig gas lossen","Bumperkleven voor minder luchtweerstand"],"major":false,"image":null,"severityReason":"Ordinary one-point practice question"},{"id":"q089","lesson":30,"text":"What should you do with an unused roof box?","options":["Leave it on permanently","Remove it","Fill it with extra weight"],"answer":1,"explanation":"Removing an unused roof box reduces aerodynamic drag and fuel consumption.","nl":"Wat doe je met een dakkoffer die je niet gebruikt?","nlOptions":["Permanent laten staan","Verwijderen","Met extra gewicht vullen"],"major":false,"image":null,"severityReason":"Ordinary one-point practice question"},{"id":"q090","lesson":30,"text":"How should you choose tyre pressure for a loaded trip?","options":["Use the manufacturer’s cold-pressure specification for the load","Add an arbitrary amount to every car","Use the lowest pressure for comfort"],"answer":0,"explanation":"Use the pressure label or handbook for your actual load, checking cold tyres. A universal pressure increase is not reliable.","nl":"Hoe kies je bandenspanning voor een beladen rit?","nlOptions":["De voorgeschreven koude spanning voor die belading","Een willekeurige verhoging voor elke auto","De laagste spanning voor comfort"],"major":false,"image":null,"severityReason":"Ordinary one-point practice question"},{"id":"q091","lesson":31,"text":"What is the legal minimum tread depth in the main grooves of a normal car tyre?","options":["0.6 mm","1.6 mm","4.0 mm"],"answer":1,"explanation":"The legal minimum is 1.6 mm. More tread can be important for good wet-road performance.","nl":"Wat is de wettelijke minimale profieldiepte in de hoofdgroeven van een gewone autoband?","nlOptions":["Nul komma zes millimeter","Eén komma zes millimeter","Vier millimeter"],"major":false,"image":null,"severityReason":"Ordinary one-point practice question"},{"id":"q092","lesson":31,"text":"During emergency braking with ABS, how should you normally use the brake pedal?","options":["Pump it rapidly","Press firmly and maintain pressure","Release it whenever it pulses"],"answer":1,"explanation":"ABS modulates braking to prevent wheel lock. Maintain firm pressure; pedal pulsation is normal.","nl":"Hoe gebruik je het rempedaal normaal bij een noodstop met ABS?","nlOptions":["Snel pompen","Stevig indrukken en druk houden","Loslaten zodra het pulseert"],"major":false,"image":null,"severityReason":"Ordinary one-point practice question"},{"id":"q093","lesson":31,"text":"Does electronic stability control allow you to ignore slippery-road conditions?","options":["Yes","No","Only with new tyres"],"answer":1,"explanation":"ESP supports stability but cannot create grip or overcome the limits of speed, tyres and road conditions.","nl":"Mag je gladde wegen negeren omdat de auto elektronische stabiliteitscontrole heeft?","nlOptions":["Ja","Nee","Alleen met nieuwe banden"],"major":false,"image":null,"severityReason":"Ordinary one-point practice question"},{"id":"q094","lesson":19,"text":"What action do these white triangular markings indicate?","options":["Give way","Accelerate","Park between the triangles"],"answer":0,"explanation":"Shark teeth mark a give-way position. Check the priority road and vulnerable users before entering.","nl":"Welke handeling geven deze witte driehoeken aan?","nlOptions":["Voorrang verlenen","Versnellen","Tussen de driehoeken parkeren"],"major":false,"image":"shark-teeth.webp","severityReason":"Ordinary one-point practice question"},{"id":"q095","lesson":2,"text":"May you cross the hatched area to reach this motorway exit at the last moment?","options":["Yes, if you indicate","No","Only if the queue is long"],"answer":1,"explanation":"Hatched areas are not drivable shortcuts. If you miss the legal exit path, continue to the next exit.","nl":"Mag je op het laatste moment over het verdrijvingsvlak naar deze afrit rijden?","nlOptions":["Ja, met richtingaanwijzer","Nee","Alleen bij een lange file"],"major":false,"image":"motorway-exit.webp","severityReason":"Ordinary one-point practice question"},{"id":"q096","lesson":26,"text":"This parking space is reserved for disabled users. Does an ordinary ticket allow you to use it?","options":["Yes","No, the appropriate valid card and conditions are required","Yes, for five minutes"],"answer":1,"explanation":"Payment alone does not grant use of a reserved accessible space. The eligible person and valid parking card requirements apply.","nl":"Deze parkeerplaats is voorbehouden voor personen met een handicap. Mag je er staan met een gewoon parkeerticket?","nlOptions":["Ja","Nee, de geldige kaart en voorwaarden zijn nodig","Ja, vijf minuten"],"major":false,"image":"accessible-parking.webp","severityReason":"Ordinary one-point practice question"},{"id":"q097","lesson":4,"text":"A car can reach only 60 km/h on level ground. Is it normally admitted to the motorway?","options":["Yes","No","Only in the right lane"],"answer":1,"explanation":"A vehicle must be capable of reaching 70 km/h on level ground for motorway access. This is an access capability rule, not a queue minimum.","nl":"Een auto kan op een vlakke weg maar zestig kilometer per uur halen. Mag die normaal de autosnelweg op?","nlOptions":["Ja","Nee","Alleen op de rechterrijstrook"],"major":false,"image":null,"severityReason":"Ordinary one-point practice question"},{"id":"q098","lesson":12,"text":"What is the normal maximum for a passenger car on a motorway without a lower posted limit?","options":["90 km/h","120 km/h","130 km/h"],"answer":1,"explanation":"The normal Belgian motorway maximum for an ordinary passenger car is 120 km/h.","nl":"Wat is de gewone maximumsnelheid voor een personenauto op een autosnelweg zonder lagere limiet?","nlOptions":["Negentig kilometer per uur","Honderdtwintig kilometer per uur","Honderddertig kilometer per uur"],"major":true,"image":null,"severityReason":"Maximum permitted speed: five-point question under Flemish exam rules"},{"id":"q099","lesson":3,"text":"At what point does a signed cycle zone normally end?","options":["At the next junction","At the end-of-cycle-zone sign","After 100 metres"],"answer":1,"explanation":"Current cycle-zone rules extend across junctions until the zone-end sign. This corrects the book’s older bicycle-street wording.","nl":"Waar eindigt een aangeduide fietszone normaal?","nlOptions":["Aan het volgende kruispunt","Aan het einde-fietszonebord","Na honderd meter"],"major":false,"image":null,"severityReason":"Ordinary one-point practice question"},{"id":"q100","lesson":18,"text":"Your light is green but traffic beyond the junction is stationary. May you enter and block the crossing road?","options":["Yes, because the light is green","No","Only with hazard lights"],"answer":1,"explanation":"Do not enter a junction if you will be stuck blocking it. Green does not remove the duty to keep it clear.","nl":"Het licht is groen maar het verkeer voorbij het kruispunt staat stil. Mag je inrijden en de kruisende weg blokkeren?","nlOptions":["Ja, want het is groen","Nee","Alleen met alarmlichten"],"major":false,"image":null,"severityReason":"Ordinary one-point practice question"},{"id":"q101","lesson":11,"text":"It is raining heavily. Are rear fog lights required?","options":["Yes","No, only fog counts","Only below 30 km/h"],"answer":0,"explanation":"Belgian rules require rear fog lights in heavy rain, as well as fog or snowfall with visibility below 100 m.","nl":"Het regent hard. Zijn de mistachterlichten verplicht?","nlOptions":["Ja","Nee, alleen bij mist","Alleen onder dertig kilometer per uur"],"major":false,"image":null,"severityReason":"Ordinary one-point practice question"},{"id":"q102","lesson":15,"text":"In a built-up area, what minimum lateral clearance should you leave when passing a cyclist?","options":["0.5 metre","1 metre","2.5 metres"],"answer":1,"explanation":"The minimum in a built-up area is 1 m. Leave more if needed; outside it, the minimum is 1.5 m.","nl":"Welke minimale zijdelingse afstand houd je bij het voorbijrijden van een fietser binnen de bebouwde kom?","nlOptions":["Een halve meter","Eén meter","Twee en een halve meter"],"major":true,"image":null,"severityReason":"Cyclist lateral clearance: Article 40ter, third degree"},{"id":"q103","lesson":13,"text":"Which factor increases reaction distance at the same speed?","options":["A longer reaction time","A brighter paint colour","A lower vehicle roof"],"answer":0,"explanation":"Distraction, fatigue or alcohol can delay your response and increase distance travelled before braking.","nl":"Welke factor vergroot de reactieafstand bij dezelfde snelheid?","nlOptions":["Een langere reactietijd","Een fellere lakkleur","Een lager autodak"],"major":false,"image":null,"severityReason":"Ordinary one-point practice question"},{"id":"q104","lesson":20,"text":"You emerge from a private driveway on another driver’s right. Do you automatically have priority?","options":["Yes","No, leaving a driveway is a manoeuvre","Only if your car is larger"],"answer":1,"explanation":"Leaving a driveway is a manoeuvre. Give way to other road users, rather than claiming priority from the right.","nl":"Je komt uit een privé-oprit rechts van een andere bestuurder. Heb je automatisch voorrang?","nlOptions":["Ja","Nee, een oprit verlaten is een manoeuvre","Alleen als je auto groter is"],"major":false,"image":null,"severityReason":"Ordinary one-point practice question"},{"id":"q105","lesson":22,"text":"A queue beyond a railway crossing leaves no room for your car. The signals permit passage. What should you do?","options":["Enter the tracks and wait","Wait before the crossing until you can clear it","Follow the car ahead closely"],"answer":1,"explanation":"Do not enter unless you can clear the railway crossing completely.","nl":"Achter een overweg laat een file geen plaats voor je auto. De signalen laten doorgang toe. Wat doe je?","nlOptions":["Op de sporen rijden en wachten","Voor de overweg wachten tot je er volledig voorbij kunt","Dicht achter de vorige auto rijden"],"major":false,"image":null,"severityReason":"Ordinary one-point practice question"}];
